"models.preferences.set": async (params) => {
  const body = params as { cwd?: string; enabledModels?: unknown };
  const cwd = resolveModelsCwd(body);
  const enabledModels = normalizeEnabledModelsInput(body.enabledModels);
  const services = await createAgentSessionServices({ cwd, agentDir: getAgentDir() });
  const { models: available } = await resolveAvailableModels(services.modelRuntime);
  if (enabledModels && !hasMatchingEnabledModel(available, enabledModels)) {
    throw new RpcError({ code: "BAD_REQUEST", message: "At least one available model must remain enabled" });
  }
  services.settingsManager.setEnabledModels(enabledModels);
  return projectModelPreferences(available, enabledModels);
},

export async function credentialStateMatches(
  runtime: Pick<CredentialRuntime, "listCredentials">,
  providerId: string,
  target: CredentialTarget,
): Promise<boolean> {
  const credentials = await runtime.listCredentials();
  const matches = credentials.some(
    (entry) => entry.providerId === providerId && (target.type === undefined || entry.type === target.type),
  );
  return target.present ? matches : !matches;
}

export async function recoverCommittedCredential(
  runtime: CredentialRuntime,
  providerId: string,
  target: CredentialTarget,
): Promise<CredentialMutationResult | null> {
  if (!(await credentialStateMatches(runtime, providerId, target))) return null;

  try {
    const result = await runtime.refresh({ allowNetwork: false, providers: [providerId] });
    if (!result.aborted && result.errors.size === 0) return { ok: true, synchronized: true };
  } catch {
    // The credential state is authoritative. Surface a safe warning below.
  }

  return {
    ok: true,
    synchronized: false,
    warning: {
      code: "MODEL_SYNC_FAILED",
      message: "Credentials were updated, but the local model state could not be refreshed. Retry model refresh.",
    },
  };
}
    "auth.setApiKey": async (params) => {
      const { provider, key } = params as { provider: string; key: string };
      if (!provider || !key?.trim()) {
        throw new RpcError({ code: "BAD_REQUEST", message: "provider and key required" });
      }
      const modelRuntime = await getSharedModelRuntime();
      let promptCount = 0;
      const interaction: AuthInteraction = {
        async prompt(request) {
          promptCount += 1;
          if (promptCount !== 1 || request.type !== "secret") {
            throw new Error(`${provider} requires an interactive, multi-field login flow`);
          }
          return key.trim();
        },
        notify() {},
      };
      try {
        await modelRuntime.login(provider, "api_key", interaction);
      } catch (error) {
        return credentialMutationFailure(modelRuntime, provider, { present: true, type: "api_key" }, error);
      }
      if (!(await credentialStateMatches(modelRuntime, provider, { present: true, type: "api_key" }))) {
        throw new RpcError({
          code: "INTERNAL",
          message: `Key for ${provider} was written but not readable back`,
        });
      }
      return { ok: true as const, synchronized: true };
    },

    "auth.deleteApiKey": async (params) => {
      const { provider } = params as { provider: string };
      const modelRuntime = await getSharedModelRuntime();
      try {
        await modelRuntime.logout(provider);
      } catch (error) {
        return credentialMutationFailure(modelRuntime, provider, { present: false, type: "api_key" }, error);
      }
      if (!(await credentialStateMatches(modelRuntime, provider, { present: false, type: "api_key" }))) {
        throw new RpcError({ code: "INTERNAL", message: `Key removal for ${provider} could not be verified` });
      }
      return { ok: true as const, synchronized: true };
    },

    "auth.logout": async (params) => {
      const { provider } = params as { provider: string };
      const modelRuntime = await getSharedModelRuntime();
      try {
        await modelRuntime.logout(provider);
      } catch (error) {
        return credentialMutationFailure(modelRuntime, provider, { present: false }, error);
      }
      if (!(await credentialStateMatches(modelRuntime, provider, { present: false }))) {
        throw new RpcError({ code: "INTERNAL", message: `Logout for ${provider} could not be verified` });
      }
      return { ok: true as const, synchronized: true };
    },

export function buildSessionHistoryPage(options: {
  entries: SessionEntry[];
  leafId?: string | null;
  historyWindow?: HistoryWindow;
  historyRevision: string;
  cursor?: HistoryCursorPayload;
}): PagedContextInfo {
  const { entries, historyWindow, historyRevision, cursor } = options;
  const anchorLeafId = cursor?.anchorLeafId ?? options.leafId ?? entries.at(-1)?.id ?? null;
  const path = buildEntryPath(entries, anchorLeafId);
  if (cursor) {
    if (cursor.historyRevision !== historyRevision) throw new StaleHistoryCursorError();
    if (path.length < cursor.anchorPathLength) throw new StaleHistoryCursorError();
    if (!path.some((entry) => entry.id === cursor.anchorLeafId)) throw new StaleHistoryCursorError();
    if (!path.some((entry) => entry.id === cursor.beforeEntryId)) throw new StaleHistoryCursorError();
  }

  if (!historyWindow && !cursor) {
    const context = buildSessionContext(entries, options.leafId);
    return {
      ...context,
      totalMessages: context.messages.length,
      loadedMessages: context.messages.length,
      truncatedBefore: false,
      historyRevision,
    };
  }

  const settings = deriveContextSettings(path);
  const allMessages = projectDisplayMessages(path);
  const beforePathIndex = cursor ? path.findIndex((entry) => entry.id === cursor.beforeEntryId) : path.length;
  if (beforePathIndex < 0) throw new StaleHistoryCursorError();
  const available = allMessages.filter((item) => item.pathIndex < beforePathIndex);
  const turns = groupTurns(available);
  const maxTurns = Math.max(1, Math.floor(historyWindow?.maxTurns ?? DEFAULT_MAX_TURNS));
  const maxBytes = Math.max(32 * 1024, Math.floor(historyWindow?.maxBytes ?? DEFAULT_MAX_BYTES));
  let selected: ProjectedMessage[] = [];

  for (let index = turns.length - 1; index >= 0 && turns.length - index <= maxTurns; index -= 1) {
    const remaining =
      maxBytes -
      RESPONSE_OVERHEAD_BYTES -
      byteLength({
        messages: selected.map((item) => item.message),
        entryIds: selected.map((item) => item.entryId),
      });
    if (remaining <= 0) break;
    const fitted = fitTurnToBudget(turns[index], remaining);
    if (!fitted) break;
    selected = [...fitted, ...selected];
  }

  const firstSelected = selected[0];
  const hasOlder = Boolean(firstSelected && allMessages.some((item) => item.pathIndex < firstSelected.pathIndex));
  const previousCursor =
    hasOlder && anchorLeafId && firstSelected
      ? encodeHistoryCursor({
          version: 1,
          historyRevision,
          anchorLeafId,
          beforeEntryId: firstSelected.entryId,
          anchorPathLength: path.length,
        })
      : undefined;

  return {
    messages: selected.map((item) => item.message),
    entryIds: selected.map((item) => item.entryId),
    ...settings,
    totalMessages: allMessages.length,
    loadedMessages: selected.length,
    truncatedBefore: hasOlder,
    ...(previousCursor ? { previousCursor } : {}),
    historyRevision,
  };
}

export class SessionIndex {
  private readonly byPath = new Map<string, IndexRecord>();
  private readonly pathById = new Map<string, string>();
  private refreshPromise: Promise<void> | null = null;
  private initialized = false;
  private projectRevision = -1;
  private projectViewsRefreshedAt = 0;
  private metrics: SessionIndexMetrics = {
    filesDiscovered: 0,
    filesParsed: 0,
    filesReused: 0,
    invalidFiles: 0,
    totalMs: 0,
  };

  private sessionsRoot(): string {
    return path.resolve(process.env.PI_CODING_AGENT_SESSION_DIR || path.join(getAgentDir(), "sessions"));
  }

  private rebuildDerivedState(): void {
    this.pathById.clear();
    const idByPath = new Map<string, string>();
    for (const record of this.byPath.values()) {
      if (record.info) {
        this.pathById.set(record.info.id, record.filePath);
        idByPath.set(record.filePath, record.info.id);
      }
    }
    for (const record of this.byPath.values()) {
      if (!record.info) continue;
      const parentSessionId = record.parentPath ? idByPath.get(record.parentPath) : undefined;
      record.info = {
        ...record.info,
        ...(parentSessionId ? { parentSessionId } : { parentSessionId: undefined }),
      };
    }
  }

  private async refreshProjectViews(): Promise<void> {
    const revision = getProjectCacheRevision();
    if (revision === this.projectRevision && Date.now() - this.projectViewsRefreshedAt < PROJECT_VIEW_TTL_MS) return;
    const projects = new Map<string, Awaited<ReturnType<typeof resolveProject>>>();
    await Promise.all(
      [...new Set([...this.byPath.values()].flatMap((record) => (record.info?.cwd ? [record.info.cwd] : [])))].map(
        async (cwd) => {
          projects.set(cwd, await resolveProject(cwd));
        },
      ),
    );
    for (const record of this.byPath.values()) {
      if (!record.info) continue;
      const project = projects.get(record.info.cwd);
      if (!project) continue;
      const { worktreeBranch: _worktreeBranch, ...base } = record.info;
      record.info = {
        ...base,
        projectRoot: project.projectRoot,
        ...(project.isWorktree && project.branch ? { worktreeBranch: project.branch } : {}),
      };
    }
    this.projectRevision = revision;
    this.projectViewsRefreshedAt = Date.now();
  }

  private async parsePath(
    filePath: string,
    currentFingerprint: Fingerprint,
    resolveProjectInfo: boolean,
  ): Promise<IndexRecord> {
    for (let attempt = 0; attempt < 2; attempt += 1) {
      const before = attempt === 0 ? currentFingerprint : fingerprint(filePath);
      try {
        const manager = SessionManager.open(filePath);
        const entries = manager.getEntries() as unknown as SessionEntry[];
        const header = manager.getHeader();
        const info = await buildSessionInfoFromManager(filePath, manager, entries, { resolveProjectInfo });
        const after = fingerprint(filePath);
        if (!sameFingerprint(before, after)) {
          if (attempt === 0) continue;
          throw new Error("session changed during index parse");
        }
        return {
          filePath,
          fingerprint: after,
          info,
          parentPath: header?.parentSession,
          valid: Boolean(info),
        };
      } catch {
        if (attempt === 0) {
          try {
            const after = fingerprint(filePath);
            if (!sameFingerprint(before, after)) continue;
          } catch {
            // File disappeared; the invalid record is removed on the next discovery pass.
          }
        }
        return { filePath, fingerprint: before, info: null, valid: false };
      }
    }
    return { filePath, fingerprint: currentFingerprint, info: null, valid: false };
  }

  initialize(): Promise<void> {
    return this.refreshAll();
  }

  refreshAll(): Promise<void> {
    if (this.refreshPromise) return this.refreshPromise;
    this.refreshPromise = (async () => {
      const startedAt = performance.now();
      const files = discoverSessionFiles(this.sessionsRoot());
      const discovered = new Set(files);
      let filesParsed = 0;
      let filesReused = 0;
      let invalidFiles = 0;

      for (const existingPath of [...this.byPath.keys()]) {
        if (!discovered.has(existingPath)) this.byPath.delete(existingPath);
      }
      for (const filePath of files) {
        let currentFingerprint: Fingerprint;
        try {
          currentFingerprint = fingerprint(filePath);
        } catch {
          continue;
        }
        const existing = this.byPath.get(filePath);
        if (existing && sameFingerprint(existing.fingerprint, currentFingerprint)) {
          filesReused += 1;
          if (!existing.valid) invalidFiles += 1;
          continue;
        }
        const record = await this.parsePath(filePath, currentFingerprint, false);
        this.byPath.set(filePath, record);
        filesParsed += 1;
        if (!record.valid) invalidFiles += 1;
      }
      this.rebuildDerivedState();
      if (filesParsed > 0) this.projectViewsRefreshedAt = 0;
      this.initialized = true;
      this.metrics = {
        filesDiscovered: files.length,
        filesParsed,
        filesReused,
        invalidFiles,
        totalMs: Math.round((performance.now() - startedAt) * 10) / 10,
      };
    })().finally(() => {
      this.refreshPromise = null;
    });
    return this.refreshPromise;
  }

  async refreshPath(filePath: string): Promise<SessionInfo | null> {
    const resolved = path.resolve(filePath);
    const root = this.sessionsRoot();
    if (resolved !== root && !resolved.startsWith(`${root}${path.sep}`)) return null;
    if (!resolved.endsWith(".jsonl") || !existsSync(resolved)) {
      this.removePath(resolved);
      return null;
    }
    let currentFingerprint: Fingerprint;
    try {
      currentFingerprint = fingerprint(resolved);
    } catch {
      this.removePath(resolved);
      return null;
    }
    const existing = this.byPath.get(resolved);
    if (existing && sameFingerprint(existing.fingerprint, currentFingerprint)) return existing.info;
    const startedAt = performance.now();
    const record = await this.parsePath(resolved, currentFingerprint, true);
    this.byPath.set(resolved, record);
    this.rebuildDerivedState();
    this.initialized = true;
    this.metrics = {
      filesDiscovered: 1,
      filesParsed: 1,
      filesReused: 0,
      invalidFiles: record.valid ? 0 : 1,
      totalMs: Math.round((performance.now() - startedAt) * 10) / 10,
    };
    return record.info;
  }

  removePath(filePath: string): SessionInfo | null {
    const existing = this.byPath.get(path.resolve(filePath));
    this.byPath.delete(path.resolve(filePath));
    this.rebuildDerivedState();
    return existing?.info ?? null;
  }

  getByPath(filePath: string): SessionInfo | null {
    return this.byPath.get(path.resolve(filePath))?.info ?? null;
  }

  async getAll(): Promise<SessionInfo[]> {
    if (!this.initialized) await this.initialize();
    await this.refreshProjectViews();
    return [...this.byPath.values()]
      .flatMap((record) => (record.info ? [record.info] : []))
      .sort((left, right) => Date.parse(right.modified) - Date.parse(left.modified));
  }

export function registerAppProtocol(): void {
  protocol.registerSchemesAsPrivileged([
    {
      scheme: "app",
      privileges: {
        standard: true,
        secure: true,
        supportFetchAPI: true,
        corsEnabled: true,
        stream: true,
      },
    },
  ]);
}

export function handleAppProtocol(rendererRoot: string): void {
  protocol.handle("app", async (request) => {
    try {
      const url = new URL(request.url);
      if (url.hostname === "preview") {
        const [token, ...assetSegments] = url.pathname.split("/").filter(Boolean);
        const preview = token ? getHtmlPreview(token) : undefined;
        if (!preview) return new Response("Not Found", { status: 404 });

        if (assetSegments.join("/") === "index.html") {
          return new Response(preview.content, {
            status: 200,
            headers: {
              "Content-Type": "text/html; charset=utf-8",
              "Content-Security-Policy": HTML_PREVIEW_CSP,
              "X-Content-Type-Options": "nosniff",
              "Referrer-Policy": "no-referrer",
            },
          });
        }

        const assetPath = resolveHtmlPreviewAssetPath(preview.filePath, assetSegments.join("/"));
        if (!assetPath) return new Response("Forbidden", { status: 403 });
        const asset = await preview.loadAsset(assetPath);
        if (asset.size > HTML_PREVIEW_ASSET_MAX_BYTES) {
          return new Response("Asset too large", { status: 413 });
        }
        const ext = path.extname(assetPath).toLowerCase();
        const mime = MIME[ext] ?? asset.mime ?? "application/octet-stream";
        return new Response(Buffer.from(asset.base64, "base64"), {
          status: 200,
          headers: {
            "Content-Type": mime,
            "Access-Control-Allow-Origin": "*",
            "X-Content-Type-Options": "nosniff",
            "Cache-Control": "no-store",
          },
        });
      }
      let pathname = decodeURIComponent(url.pathname);
      if (pathname.startsWith("/bundle")) {
        pathname = pathname.slice("/bundle".length) || "/";
      }
      if (pathname === "/" || pathname === "") pathname = "/index.html";

      const filePath = path.normalize(path.join(rendererRoot, pathname));
      if (!filePath.startsWith(path.normalize(rendererRoot))) {
        return new Response("Forbidden", { status: 403 });
      }

      if (!fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
        // SPA fallback
        const index = path.join(rendererRoot, "index.html");
        if (fs.existsSync(index)) {
          const body = fs.readFileSync(index);
          return new Response(body, {
            status: 200,
            headers: {
              "Content-Type": "text/html; charset=utf-8",
              "Content-Security-Policy": CSP,
            },
          });
        }
        return new Response("Not Found", { status: 404 });
      }

      const ext = path.extname(filePath).toLowerCase();
      const mime = MIME[ext] ?? "application/octet-stream";
      const data = fs.readFileSync(filePath);
      return new Response(data, {
        status: 200,
        headers: {
          "Content-Type": mime,
          "Content-Security-Policy": CSP,
          "X-Content-Type-Options": "nosniff",
        },
      });
    } catch (err) {
      appendMainLog(`protocol.handle error: ${err}`);
      return new Response("Internal Error", { status: 500 });
    }
  });
}

export function resolveRendererEntry(isDev: boolean, mainDirectory = __dirname): string {
  // Explicit Vite URL (npm run dev sets this)
  if (process.env.VITE_DEV_SERVER_URL) {
    return process.env.VITE_DEV_SERVER_URL;
  }
  // Prefer built renderer whenever it exists (works for `npm start` after build)
  const builtIndex = path.join(mainDirectory, "..", "renderer", "index.html");
  if (fs.existsSync(builtIndex)) {
    return "app://bundle/index.html";
  }
  // Dev without prior build: expect Vite on 5173
  if (isDev) {
    return "http://localhost:5173";
  }
  return "app://bundle/index.html";
}

async connectAccount(account: ChannelAccountConfig): Promise<ChannelsSnapshot> {
  if (this.config.getAccount(account.id)) throw new Error("消息渠道账号已存在，请使用凭证更新功能");
  const secret = await this.getSecret(account);
  if (!secret) throw new Error("消息渠道凭证尚未写入系统安全存储");

  try {
    const probe = await this.registry.get(account.channel).probe(account, secret);
    if (!probe.ok) throw new Error(probe.message);
    const providerAccountId = probe.providerAccountId ?? secret.providerAccountId;
    const providerUsername = probe.providerUsername ?? secret.providerUsername;
    await this.setSecret(account.channel, account.id, {
      ...secret,
      providerAccountId,
      ...(providerUsername ? { providerUsername } : {}),
    });
    const saved = this.config.upsertAccount({
      ...account,
      name: account.name.trim() || providerUsername || probe.displayName || `${account.channel} ${providerAccountId}`,
      enabled: true,
      providerAccountId,
      ...(providerUsername ? { providerUsername } : {}),
      updatedAt: new Date().toISOString(),
    });
    await this.restartAccount(saved.id);
    return this.snapshot();
  } catch (error) {
    await this.deleteSecret(account).catch(() => undefined);
    this.config.deleteAccount(account.id);
    this.state.deleteAccount(account.id);
    this.statuses.delete(account.id);
    throw error;
  }
}

export class ChannelConfigStore {
  private data: ChannelConfigFile;
  private readonly filePath: string;

  constructor(filePath: string) {
    this.filePath = filePath;
    this.data = this.read();
  }

  private read(): ChannelConfigFile {
    if (!existsSync(this.filePath)) return structuredClone(EMPTY_CONFIG);
    try {
      const parsed = JSON.parse(readFileSync(this.filePath, "utf8")) as Partial<ChannelConfigFile>;
      // Versionless development snapshots are migrated as v0.
      if (parsed.version !== undefined && parsed.version !== 1) {
        throw new Error(`Unsupported channels config version: ${String(parsed.version)}`);
      }
      const migrated = {
        version: 1 as const,
        accounts: Array.isArray(parsed.accounts) ? parsed.accounts.map((account) => normalizeAccount(account)) : [],
        bindings: Array.isArray(parsed.bindings) ? parsed.bindings.map(normalizeBinding) : [],
      };
      if (parsed.version === undefined) atomicWrite(this.filePath, migrated);
      return migrated;
    } catch (error) {
      if (error instanceof SyntaxError) {
        renameSync(this.filePath, `${this.filePath}.corrupt-${Date.now()}`);
        return structuredClone(EMPTY_CONFIG);
      }
      throw error;
    }
  }

  private persist(): void {
    atomicWrite(this.filePath, this.data);
  }

  listAccounts(): ChannelAccountConfig[] {
    return structuredClone(this.data.accounts);
  }

  getAccount(accountId: string): ChannelAccountConfig | undefined {
    const found = this.data.accounts.find((account) => account.id === accountId);
    return found ? structuredClone(found) : undefined;
  }

  upsertAccount(account: ChannelAccountConfig): ChannelAccountConfig {
    const normalized = normalizeAccount(account, true);
    if (!normalized.id) throw new Error("Channel account id is required");
    const index = this.data.accounts.findIndex((item) => item.id === normalized.id);
    if (index >= 0) {
      normalized.createdAt = this.data.accounts[index].createdAt;
      this.data.accounts[index] = normalized;
    } else {
      this.data.accounts.push(normalized);
    }
    this.persist();
    return structuredClone(normalized);
  }

  deleteAccount(accountId: string): void {
    this.data.accounts = this.data.accounts.filter((account) => account.id !== accountId);
    this.data.bindings = this.data.bindings.filter((binding) => binding.accountId !== accountId);
    this.persist();
  }

  listBindings(): ChannelBinding[] {
    return structuredClone(this.data.bindings);
  }

  upsertBinding(binding: ChannelBinding): ChannelBinding {
    const normalized = normalizeBinding(binding);
    if (!normalized.id || !normalized.accountId || !normalized.peerId) throw new Error("Invalid channel binding");
    const index = this.data.bindings.findIndex((item) => item.id === normalized.id);
    if (index >= 0) {
      normalized.createdAt = this.data.bindings[index].createdAt;
      this.data.bindings[index] = normalized;
    } else {
      this.data.bindings.push(normalized);
    }
    this.persist();
    return structuredClone(normalized);
  }

  deleteBinding(bindingId: string): void {
    this.data.bindings = this.data.bindings.filter((binding) => binding.id !== bindingId);
    this.persist();
  }
}
function atomicWrite(filePath: string, value: unknown): void {
  mkdirSync(path.dirname(filePath), { recursive: true });
  const temp = `${filePath}.${process.pid}.${Date.now()}.tmp`;
  writeFileSync(temp, JSON.stringify(value, null, 2), { encoding: "utf8", mode: 0o600 });
  try {
    renameSync(temp, filePath);
    try {
      chmodSync(filePath, 0o600);
    } catch {
      /* best effort on Windows */
    }
  } catch (error) {
    try {
      unlinkSync(temp);
    } catch {
      /* ignore cleanup failure */
    }
    throw error;
  }
}

downloadUpdate(): Promise<DesktopUpdateState> {
  const unavailable = this.requireEnabled();
  if (unavailable) return Promise.reject(unavailable);

  const active = this.reuseOrReject<DesktopUpdateState>("download");
  if (active) return active;
  if (this.state.phase !== "available") {
    return Promise.reject(this.invalidState("download an update"));
  }

  this.transition("downloading", { percent: 0, transferred: 0 });
  this.downloadEventReceived = false;
  this.downloadPromiseSettled = false;
  this.log("info", `downloading update ${this.details.availableVersion ?? "(unknown version)"}`);

  return this.trackOperation("download", async () => {
    try {
      await this.downloadWithWatchdog();
      this.downloadPromiseSettled = true;
      if (this.downloadEventReceived && this.state.phase === "downloading") {
        this.finishDownloadedUpdate();
      }
    } catch (error) {
      if (this.state.phase !== "error") this.recordAdapterError(error, "download");
    }
    return this.getState();
  });
}

installUpdate(): Promise<void> {
  const unavailable = this.requireEnabled();
  if (unavailable) return Promise.reject(unavailable);

  const active = this.reuseOrReject<void>("install");
  if (active) return active;
  if (this.state.phase !== "downloaded") {
    return Promise.reject(this.invalidState("install an update"));
  }
  if (this.runningSessionCount > 0) {
    return Promise.reject(
      new UpdateManagerError(
        "UPDATE_BUSY",
        "Active agent sessions must finish before the downloaded update can be installed.",
      ),
    );
  }

  return this.trackOperation("install", async () => {
    this.transition("installing");
    this.log("info", `installing update ${this.details.availableVersion ?? "(unknown version)"}`);
    try {
      this.installLifecyclePrepared = true;
      await this.prepareToInstall();
      this.adapter!.quitAndInstall(false, true);
    } catch (error) {
      if (this.state.phase !== "error") this.recordAdapterError(error, "install");
      await this.recoverInstallLifecycle();
      const code = this.state.error?.code ?? classifyUpdateError(error, "install");
      throw new UpdateManagerError(code, ERROR_MESSAGES[code]);
    }
  });
}

  this.state = {
    phase: this.enabled ? "idle" : "disabled",
    currentVersion: this.currentVersion,
    automaticChecksEnabled: options.automaticChecksEnabled ?? true,
    installBlockedByActiveSessions: false,
    canRetry: false,
  };

  if (this.enabled && this.adapter) this.bindAdapterEvents(this.adapter);
}
startAutomaticChecks(): void {
  if (this.disposed || this.automaticChecksStarted) return;
  this.automaticChecksStarted = true;
  if (this.enabled && this.state.automaticChecksEnabled) {
    this.scheduleAutomaticCheck(this.initialCheckDelayMs);
  }
}

stopAutomaticChecks(): void {
  this.automaticChecksStarted = false;
  this.cancelAutomaticTimer();
}

async stop(
  processId: string,
  runId: string,
  mode: ManagedProcessStopMode = "graceful",
  source: ManagedProcessStopSource = "user",
  ownerSessionId?: string,
): Promise<ManagedProcessPublicInfo> {
  const record = this.requireRecord(processId, ownerSessionId);
  this.assertRun(record, runId);
  if (terminalState(record.state)) return this.publicInfo(record);
  if (source === "user") record.userStopBarrier = true;
  record.stopSource = source;
  record.state = "stopping";
  this.append(record, "system", `Stop requested by ${source} (${mode})`);
  this.emitChanged(record, "state");
  if (!record.backend) {
    record.state = "killed";
    record.stoppedAt = this.now();
    record.stdinOpen = false;
    record.exit = { code: null, reason: "stopped", stoppedBy: source, finishedAt: this.now() };
    record.finish?.resolve();
    this.emitChanged(record, "exit");
    return this.publicInfo(record);
  }
  try {
    await record.backend.stop(mode, source);
  } catch {
    // The timeout cleanup below disposes the backend containment.
  }
  try {
    await timeout(
      record.finish?.promise ?? Promise.resolve(),
      STOP_TOTAL_TIMEOUT_MS,
      "Managed process did not stop in time",
    );
  } catch (error) {
    await record.backend.dispose();
    if (!terminalState(record.state)) {
      this.containmentFailed = true;
      record.state = "lost";
      record.stoppedAt = this.now();
      record.stdinOpen = false;
      record.exit = { code: null, reason: "host-failure", stoppedBy: source, finishedAt: this.now() };
      this.append(record, "system", "Managed process cleanup could not be verified; new starts are disabled");
      this.emitChanged(record, "exit");
      record.finish?.resolve();
    }
    if (!terminalState(record.state)) {
      record.state = "killed";
      record.stoppedAt = this.now();
      record.exit = { code: null, reason: "stopped", stoppedBy: source, finishedAt: this.now() };
      this.emitChanged(record, "exit");
      record.finish?.resolve();
    }
    if (error instanceof ManagedProcessError && mode !== "force") {
      this.append(record, "system", "Graceful stop timed out; process tree was force terminated");
    }
  }
  return this.publicInfo(record);
}
async restart(
  processId: string,
  runId: string,
  source: "agent" | "user",
  ownerSessionId?: string,
  trusted = true,
): Promise<ManagedProcessPublicInfo> {
  const record = this.requireRecord(processId, ownerSessionId);
  this.assertRun(record, runId);
  if (source === "agent" && record.userStopBarrier) {
    throw new ManagedProcessError(
      "PROCESS_USER_STOPPED",
      "The user stopped this process; only a user restart can clear the barrier",
    );
  }
  if (!terminalState(record.state)) await this.stop(processId, runId, "graceful", source, ownerSessionId);
  this.assertRun(record, runId);
  if (source === "agent" && record.userStopBarrier) {
    throw new ManagedProcessError(
      "PROCESS_USER_STOPPED",
      "The user stopped this process; only a user restart can clear the barrier",
    );
  }
  if (source === "user") record.userStopBarrier = false;
  await this.assertStartEnabled();
  this.assertRun(record, runId);
  if (source === "agent" && record.userStopBarrier) {
    throw new ManagedProcessError(
      "PROCESS_USER_STOPPED",
      "The user stopped this process; only a user restart can clear the barrier",
    );
  }
  if (!trusted)
    throw new ManagedProcessError(
      "PROCESS_PROJECT_UNTRUSTED",
      "Project trust is required to restart a managed process",
    );

  record.generation += 1;
  record.restartCount += 1;
  record.runId = randomUUID();
  record.state = "restarting";
  record.readiness = record.readinessSpec.type === "none" ? "not-requested" : "pending";
  record.readinessMatched = undefined;
  record.startedAt = undefined;
  record.stoppedAt = undefined;
  record.exit = undefined;
  record.stdinOpen = true;
  record.endpoints = [];
  record.networkWarnings = managedProcessNetworkWarnings(record.command);
  record.output = new ManagedProcessOutputBuffer(record.runId);
  record.decoder = this.createDecoder(record);
  record.removeBackendListener?.();
  record.backend = undefined;
  record.removeBackendListener = undefined;
  record.finish = undefined;
  record.reaper = undefined;
  record.reaperRegistered = false;
  record.stopSource = undefined;
  record.stdinWindow = [];
  this.emitChanged(record, "state");
  try {
    await this.startRun(record, trusted);
    return this.publicInfo(record);
  } catch (error) {
    await this.cleanupFailedRun(record);
    if (!terminalState(record.state)) {
      record.state = "failed";
      record.exit = { code: null, reason: "error", finishedAt: this.now() };
      record.stoppedAt = this.now();
      this.append(record, "system", boundedSystemMessage(error instanceof Error ? error.message : String(error)));
      this.emitChanged(record, "exit");
    }
    throw toolchainError(error);
  }
}

private updateReadiness(record: ManagedRecord, text: string): void {
  if (record.state !== "starting" && record.state !== "running") return;
  if (record.readinessSpec.type !== "output" || record.readiness === "ready") return;
  if (!text.includes(record.readinessSpec.contains)) return;
  record.readiness = "ready";
  record.readinessMatched = record.readinessSpec.contains;
  record.state = "ready";
  this.emitChanged(record, "readiness");
}

private async observeInitialWindow(record: ManagedRecord): Promise<void> {
  if (record.readinessSpec.type === "none") {
    if (record.output.allRecords().some((item) => item.stream === "stdout" || item.stream === "stderr")) return;
    await new Promise<void>((resolve) => {
      const waiter: Waiter = { resolve };
      record.waiters.add(waiter);
      const timer = setTimeout(() => {
        record.waiters.delete(waiter);
        resolve();
      }, MANAGED_PROCESS_LIMITS.startWaitDefaultMs);
      timer.unref();
      waiter.resolve = () => {
        if (
          !terminalState(record.state) &&
          !record.output.allRecords().some((item) => item.stream === "stdout" || item.stream === "stderr")
        ) {
          return;
        }
        clearTimeout(timer);
        record.waiters.delete(waiter);
        resolve();
      };
    });
    return;
  }
  const timeoutMs = normalizeManagedWaitMs(record.readinessSpec.timeoutMs, true);
  if (record.readiness === "ready" || terminalState(record.state)) return;
  await new Promise<void>((resolve) => {
    const waiter: Waiter = { resolve };
    record.waiters.add(waiter);
    const timer = setTimeout(() => {
      record.waiters.delete(waiter);
      resolve();
    }, timeoutMs);
    timer.unref();
    waiter.resolve = () => {
      if (record.readiness !== "ready" && !terminalState(record.state)) return;
      clearTimeout(timer);
      record.waiters.delete(waiter);
      resolve();
    };
  });
  if ((record.readiness as ManagedProcessReadiness) !== "ready" && !terminalState(record.state)) {
    record.readiness = "timed-out";
    this.emitChanged(record, "readiness");
  }
}

