export function resolveRendererEntry(isDev: boolean, mainDirectory = __dirname): string {
  // Explicit Vite URL (npm run dev sets this)
  if (process.env.VITE_DEV_SERVER_URL) {
    return process.env.VITE_DEV_SERVER_URL;
  }
  // Prefer built renderer whenever it exists (works for `npm start` after build)
  const builtIndex = path.join(mainDirectory, "..", "renderer", "index.html");
  if (fs.existsSync(builtIndex)) {
    return "app://bundle/index.html";
  }
  // Dev without prior build: expect Vite on 5173
  if (isDev) {
    return "http://localhost:5173";
  }
  return "app://bundle/index.html";
}

export function buildPublicToolchainState(options: {
  revision: number;
  platform: NodeJS.Platform;
  arch: string;
  candidates: readonly ToolCandidate[];
  defaults: Readonly<Partial<Record<ToolCapabilityId, ToolCandidate>>>;
  preferences: Readonly<Partial<Record<ToolCapabilityId, ToolPreference>>>;
  redactionRoots: readonly PathRedactionRoot[];
  scanComplete: boolean;
  stateReadOnly?: boolean;
  components?: Readonly<Partial<Record<ManagedComponentId, PublicManagedComponentState>>>;
  caches?: PublicToolchainState["caches"];
  operations?: PublicToolchainState["operations"];
  lastScanAt?: string;
  lastErrorCode?: PublicToolchainState["lastErrorCode"];
}): PublicToolchainState {
  const capabilities: PublicToolchainState["capabilities"] = {};
  for (const capability of TOOL_CAPABILITY_IDS) {
    const preference = options.preferences[capability] ?? "auto";
    const allCandidates = options.candidates.filter((candidate) => candidate.capability === capability);
    const selected = options.defaults[capability];
    const representative = selected ?? allCandidates[0];
    capabilities[capability] = {
      capability,
      preference,
      provider: selected?.provider ?? representative?.provider,
      version: selected?.version ?? representative?.version,
      pathLabel: representative
        ? redactToolPath(representative.executable, options.redactionRoots, options.platform)
        : undefined,
      health: selected ? "healthy" : (representative?.health ?? "missing"),
      reasonCode: selected ? undefined : (representative?.reasonCode ?? MISSING_REASON[capability]),
      candidates: allCandidates.map((candidate) => ({
        id: candidate.id,
        capability,
        provider: candidate.provider,
        version: candidate.version,
        pathLabel: redactToolPath(candidate.executable, options.redactionRoots, options.platform),
        health: candidate.health,
        reasonCode: candidate.reasonCode,
      })),
    };
  }

  const components: PublicToolchainState["components"] = {};
  for (const componentId of MANAGED_COMPONENT_IDS) {
    components[componentId] = options.components?.[componentId] ?? emptyPublicComponentState(componentId);
  }

  return {
    schemaVersion: 1,
    revision: options.revision,
    platform: options.platform,
    arch: options.arch,
    coreReady: options.scanComplete,
    stateReadOnly: options.stateReadOnly,
    capabilities,
    components,
    caches: options.caches ? structuredClone(options.caches) : {},
    operations: options.operations ? options.operations.map((operation) => structuredClone(operation)) : [],
    lastScanAt: options.lastScanAt,
    lastErrorCode: options.lastErrorCode,
  };
}

export function createToolchainBashOptions(
  context: ToolExecutionContext,
  runtime: ToolchainRuntime = toolchainRuntime,
  commandPrefix?: string,
  beforeExec?: (command: string) => Promise<void>,
): BashToolOptions {
  const descriptor = context.commands["shell.bash"];
  if (!descriptor) {
    return {
      commandPrefix,
      operations: {
        async exec() {
          runtime.requireFromContext("shell.bash", context);
          return { exitCode: null };
        },
      },
    };
  }
  const local = createLocalBashOperations({ shellPath: descriptor.executable });
  return {
    commandPrefix,
    shellPath: descriptor.executable,
    operations: {
      async exec(command, cwd, options) {
        await beforeExec?.(command);
        return local.exec(command, cwd, options);
      },
    },
    spawnHook(spawnContext) {
      return {
        ...spawnContext,
        env: sanitizeToolEnvironment({ ...spawnContext.env, ...context.shellEnv }),
      };
    },
  };
}
export function createToolchainGitRunner(runtime: ToolchainRuntime = toolchainRuntime): GitCommandRunner {
  return {
    async run(cwd, args, options) {
      const result = await runtime.exec("vcs.git", ["-C", cwd, ...args], {
        cwd,
        intent: "git-operation",
        env: options.env,
        timeout: options.timeout,
        maxBuffer: options.maxBuffer,
      });
      return { stdout: result.stdout };
    },
  };
}

export function installToolchainGitRunner(runtime: ToolchainRuntime = toolchainRuntime): () => void {
  return setGitCommandRunner(createToolchainGitRunner(runtime));
}

async function searchSkillsApi(query: string, limit: number): Promise<SkillSearchResult[]> {
  const url = `${SEARCH_API_BASE}/api/search?q=${encodeURIComponent(query)}&limit=${limit}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`skills.sh search failed: HTTP ${res.status}`);
  const data = (await res.json()) as {
    skills?: Array<{ id?: string; name?: string; source?: string; installs?: number }>;
  };
  return normalizeSkillsApiResults(data.skills ?? [], SEARCH_API_BASE);
}

export async function searchSkills(query: string, limit = 50): Promise<{ results: SkillSearchResult[] }> {
  const q = query.trim();
  if (!q) return { results: [] };
  const capped = Math.min(50, Math.max(1, limit));

  try {
    const results = await searchSkillsApi(q, capped);
    return { results };
  } catch {
    const { stdout, stderr } = await runNpx(buildSkillsCliArgs(["find", q]), {
      timeout: 60_000,
      env: { FORCE_COLOR: "0" },
    });
    return { results: parseSkillsSearchOutput(stdout + stderr).slice(0, capped) };
  }
}

export async function installSkill(params: {
  package: string;
  scope?: "global" | "project";
  cwd?: string;
}): Promise<{ ok: true; output: string }> {
  const pkg = params.package?.trim();
  if (!pkg) throw new Error("package required");

  const isGlobal = params.scope !== "project";
  const args = buildSkillsCliArgs(["add", pkg, "-y", "--agent", "pi"]);
  if (isGlobal) args.push("-g");

  try {
    const { stdout, stderr } = await runNpx(args, {
      timeout: 180_000,
      cwd: !isGlobal && params.cwd ? params.cwd : undefined,
      env: { FORCE_COLOR: "0" },
    });
    const output = (stdout + stderr).replace(ANSI_RE, "");
    const success = /Installation complete|Installed \d+ skill/.test(output);
    if (!success) throw new Error(output.slice(-300) || "Install failed");
    return { ok: true as const, output };
  } catch (e: unknown) {
    if (e instanceof ToolchainError) throw e;
    const err = e as { stdout?: string; stderr?: string; message?: string };
    const output = ((err.stdout ?? "") + (err.stderr ?? "")).replace(ANSI_RE, "");
    throw new Error(output || err.message || String(e));
  }
}

const CRASH_WINDOW_MS = 30_000;
const MAX_RESTARTS = 2;
const PING_INTERVAL_MS = 15_000;
const PING_TIMEOUT_MS = 10_000;
  private scheduleRestart(reason: string): void {
    if (this.status === "stopped") return;

    const reservation = reserveHostRestart(this.restartTimes, Date.now(), CRASH_WINDOW_MS, MAX_RESTARTS);
    this.restartTimes = reservation.restartTimes;
    if (reservation.attempt === null) {
      appendMainLog(`${reason}; restart budget exhausted`);
      this.setStatus("crashed", `${reason} and restart budget exhausted`);
      return;
    }

    appendMainLog(`restarting agent-host (attempt ${reservation.attempt}/${MAX_RESTARTS}): ${reason}`);
    this.setStatus("starting", `${reason}; restarting`);
    setTimeout(() => {
      if (this.status === "starting" && !this.child) this.spawn();
    }, 500).unref();
  }

  private startPing(): void {
    this.clearPing();
    this.lastPingTick = Date.now();
    this.pingTimer = setInterval(() => {
      if (!this.child) return;
      const now = Date.now();
      const heartbeat = evaluateHeartbeatTick({
        now,
        lastTickAt: this.lastPingTick,
        lastAcknowledgedAt: this.lastPong,
        intervalMs: PING_INTERVAL_MS,
        timeoutMs: PING_TIMEOUT_MS,
      });
      this.lastPingTick = now;
      if (heartbeat.clockDiscontinuity) this.lastPong = now;
      if (heartbeat.timedOut) {
        appendMainLog("agent-host ping timeout — killing");
        try {
          this.child.kill();
        } catch {
          /* ignore */
        }
        return;
      }
      try {
        this.child.postMessage({ type: "ping" });
      } catch {
        /* ignore */
      }
    }, PING_INTERVAL_MS);
  }

function requestContext(port: AnyMessagePort): RpcRequestContext {
  return {
    setLease(key, release) {
      if (!ports.has(port)) {
        release();
        return;
      }
      const leases = portLeases.get(port) ?? new Map<string, () => void>();
      const previous = leases.get(key);
      leases.set(key, release);
      portLeases.set(port, leases);
      if (previous && previous !== release) previous();
    },
    releaseLease(key) {
      const leases = portLeases.get(port);
      const release = leases?.get(key);
      if (!release) return false;
      leases?.delete(key);
      try {
        release();
      } catch {
        /* isolate explicit resource release */
      }
      return true;
    },
  };
}
  attachPort(port) {
    if (ports.has(port)) return;
    ports.add(port);
    ensureSubs(port);
    portLeases.set(port, new Map());
    const unlisten = listenPort(port, (data) => {
      void onPortMessage(port, data);
    });
    portUnlisten.set(port, unlisten);
    // ISSUE-013: drop port when remote closes
    const onClose = () => {
      forgetPort(port);
    };
    if (typeof port.addEventListener === "function") {
      port.addEventListener("close", onClose as (ev: { data: unknown }) => void);
      portCloseUnlisten.set(port, () => {
        port.removeEventListener?.("close", onClose as (ev: { data: unknown }) => void);
      });
    } else if (typeof port.on === "function") {
      port.on("close", onClose);
      portCloseUnlisten.set(port, () => {
        if (typeof port.off === "function") port.off("close", onClose);
        else port.removeListener?.("close", onClose);
