export function registerAppProtocol(): void {
  protocol.registerSchemesAsPrivileged([
    {
      scheme: "app",
      privileges: {
        standard: true,
        secure: true,
        supportFetchAPI: true,
        corsEnabled: true,
        stream: true,
      },
    },
  ]);
}

export function handleAppProtocol(rendererRoot: string): void {
  protocol.handle("app", async (request) => {
    try {
      const url = new URL(request.url);
      if (url.hostname === "preview") {
        const [token, ...assetSegments] = url.pathname.split("/").filter(Boolean);
        const preview = token ? getHtmlPreview(token) : undefined;
        if (!preview) return new Response("Not Found", { status: 404 });

        if (assetSegments.join("/") === "index.html") {
          return new Response(preview.content, {
            status: 200,
            headers: {
              "Content-Type": "text/html; charset=utf-8",
              "Content-Security-Policy": HTML_PREVIEW_CSP,
              "X-Content-Type-Options": "nosniff",
              "Referrer-Policy": "no-referrer",
            },
          });
        }

        const assetPath = resolveHtmlPreviewAssetPath(preview.filePath, assetSegments.join("/"));
        if (!assetPath) return new Response("Forbidden", { status: 403 });
        const asset = await preview.loadAsset(assetPath);
        if (asset.size > HTML_PREVIEW_ASSET_MAX_BYTES) {
          return new Response("Asset too large", { status: 413 });
        }
        const ext = path.extname(assetPath).toLowerCase();
        const mime = MIME[ext] ?? asset.mime ?? "application/octet-stream";
        return new Response(Buffer.from(asset.base64, "base64"), {
          status: 200,
          headers: {
            "Content-Type": mime,
            "Access-Control-Allow-Origin": "*",
            "X-Content-Type-Options": "nosniff",
            "Cache-Control": "no-store",
          },
        });
      }
      let pathname = decodeURIComponent(url.pathname);
      if (pathname.startsWith("/bundle")) {
        pathname = pathname.slice("/bundle".length) || "/";
      }
      if (pathname === "/" || pathname === "") pathname = "/index.html";

      const filePath = path.normalize(path.join(rendererRoot, pathname));
      if (!filePath.startsWith(path.normalize(rendererRoot))) {
        return new Response("Forbidden", { status: 403 });
      }

      if (!fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
        // SPA fallback
        const index = path.join(rendererRoot, "index.html");
        if (fs.existsSync(index)) {
          const body = fs.readFileSync(index);
          return new Response(body, {
            status: 200,
            headers: {
              "Content-Type": "text/html; charset=utf-8",
              "Content-Security-Policy": CSP,
            },
          });
        }
        return new Response("Not Found", { status: 404 });
      }

      const ext = path.extname(filePath).toLowerCase();
      const mime = MIME[ext] ?? "application/octet-stream";
      const data = fs.readFileSync(filePath);
      return new Response(data, {
        status: 200,
        headers: {
          "Content-Type": mime,
          "Content-Security-Policy": CSP,
          "X-Content-Type-Options": "nosniff",
        },
      });
    } catch (err) {
      appendMainLog(`protocol.handle error: ${err}`);
      return new Response("Internal Error", { status: 500 });
    }
  });
}

const DEFAULT_INITIAL_CHECK_DELAY_MS = 60_000;
const DEFAULT_CHECK_INTERVAL_MS = 6 * 60 * 60 * 1_000;
const DEFAULT_DOWNLOAD_WATCHDOG_MS = 15 * 60 * 1_000;
const DEFAULT_JITTER_RATIO = 0.08;

private async handleInbound(envelope: InboundEnvelope): Promise<void> {
  await this.lanes.run(routeKey(envelope), async () => {
    const account = this.config.getAccount(envelope.accountId);
    if (!account || !account.enabled) return;
    const secret = await this.getSecret(account);
    if (!secret) throw new Error("Channel credential is unavailable");
    const decision = evaluateInboundPolicy(account, envelope);
    if (decision === "ignore") {
      this.addActivity({
        channel: account.channel,
        accountId: account.id,
        direction: "inbound",
        outcome: "ignored",
        peerId: envelope.peer.id,
        detail: "访问策略拒绝",
      });
      return;
    }
    if (decision === "pair") {
      await this.handlePairing(account, envelope, secret);
      this.addActivity({
        channel: account.channel,
        accountId: account.id,
        direction: "inbound",
        outcome: "ignored",
        peerId: envelope.peer.id,
        detail: "等待配对批准",
      });
      return;
    }
    if (!envelope.text.trim() && envelope.attachments.length === 0) {
      const label = "消息内容为空。";
      const receipt = await this.registry.get(account.channel).send({
        account,
        secret,
        peerId: envelope.peer.id,
        contextToken: envelope.providerContext?.contextToken,
        threadId: envelope.threadId,
        replyToMessageId: envelope.providerContext?.replyToMessageId,
        text: label,
      });
      this.state.addDelivery(receipt);
      return;
    }

    const binding = this.resolveBinding(account, envelope);
    const adapter = this.registry.get(account.channel);
    let stagedAttachments: StagedInboundAttachment[] = [];
    if (envelope.attachments.length > 0 && adapter.downloadInbound) {
      try {
        if (envelope.attachments.length > CHANNEL_MEDIA_MAX_ATTACHMENTS) {
          throw new Error(`单条消息最多支持 ${CHANNEL_MEDIA_MAX_ATTACHMENTS} 个附件`);
        }
        const downloaded = await adapter.downloadInbound({ account, secret, envelope });
        stagedAttachments = await this.media.stage(account.id, envelope.id, downloaded);
      } catch (error) {
        this.log(`[${account.id}] media download failed: ${safeChannelError(error)}`);
        const receipt = await adapter.send({
          account,
          secret,
          peerId: envelope.peer.id,
          contextToken: envelope.providerContext?.contextToken,
          threadId: envelope.threadId,
          replyToMessageId: envelope.providerContext?.replyToMessageId,
          text: "附件下载或校验失败。请确认文件不超过 20 MiB，并重新发送受支持的图片、文件或语音。",
        });
        this.state.addDelivery(receipt);
        this.addActivity({
          channel: account.channel,
          accountId: account.id,
          direction: "inbound",
          outcome: "ignored",
          peerId: envelope.peer.id,
          detail: "附件处理失败",
        });
        return;
      }
    }
    if (!envelope.text.trim() && stagedAttachments.length === 0) {
      const receipt = await adapter.send({
        account,
        secret,
        peerId: envelope.peer.id,
        contextToken: envelope.providerContext?.contextToken,
        threadId: envelope.threadId,
        replyToMessageId: envelope.providerContext?.replyToMessageId,
        text: "当前渠道或消息类型尚不支持该媒体附件。",
      });
      this.state.addDelivery(receipt);
      return;
    }
    this.addActivity({
      channel: account.channel,
      accountId: account.id,
      direction: "inbound",
      outcome: "accepted",
      peerId: envelope.peer.id,
    });
    await adapter
      .setTyping?.({
        account,
        secret,
        peerId: envelope.peer.id,
        contextToken: envelope.providerContext?.contextToken,
        threadId: envelope.threadId,
        typing: true,
      })
      .catch(() => undefined);
    let progressiveOutput: AdapterTurnOutput | undefined;
    try {
