          error?: { message?: string };
        };
        if (message.kind !== "response" || message.id !== id) return;
        cleanup();
        if (message.ok) resolve(message.result as T);
        else reject(new Error(message.error?.message ?? `Host RPC failed: ${method}`));
      });
      port1.start();
      port1.postMessage({ kind: "request", id, method, params });
    });
  }

  private setStatus(s: HostStatus, detail?: string): void {
    this.status = s;
    this.onStatusChange?.(s, detail);
  }

  private spawn(): void {
    appendMainLog(`spawning agent-host: ${this.hostEntry}`);
    // A replacement utility process must acknowledge both policy snapshots
    // itself; an acknowledgement from the previous Host is not transferable.
    this.toolchainAckRevision = -1;
    this.browserAckRevision = -1;
    this.hostInstanceId = randomUUID();
    this.managedProcessOwnerReady = false;
    this.setStatus("starting");

    // utilityProcess.fork rejects undefined env values
    const env: Record<string, string> = {};
    for (const [k, v] of Object.entries(process.env)) {
      if (typeof v === "string") env[k] = v;
    }
    // Host must NOT run as pure node — it needs parentPort from utilityProcess
    delete env.ELECTRON_RUN_AS_NODE;
    env.PI_AGENT_HOST = "1";
    env.PI_DESKTOP_USER_DATA = app.getPath("userData");
    env.PI_DESKTOP_VERSION = app.getVersion();

    const spawnResult = trySpawnHost(() =>
      utilityProcess.fork(this.hostEntry, [], {
        serviceName: "pi-agent-host",
        stdio: "pipe",
        env,
      }),
    );
    if (!spawnResult.ok) {
      appendMainLog(`agent-host spawn failed: ${spawnResult.error}`);
      this.scheduleRestart(`Host failed to spawn: ${spawnResult.error}`);
      return;
    }
    const child = spawnResult.child;
    const exitSignal = createHostExitSignal();
    const stdoutBuffer = new HostOutputLineBuffer((lines) => appendMainLogs(lines.map((line) => `[host:out] ${line}`)));
    const stderrBuffer = new HostOutputLineBuffer((lines) => appendMainLogs(lines.map((line) => `[host:err] ${line}`)));

    this.child = child;
    this.childExitSignal = exitSignal;
    this.lastPong = Date.now();

    child.on("spawn", () => {
      appendMainLog("agent-host spawned");
      // Flush any pending ports
      for (const port of this.pendingPorts.splice(0)) {
        try {
          child.postMessage({ type: "attach-port" }, [port]);
        } catch (err) {
          appendMainLog(`flush pending port failed: ${err}`);
        }
      }
    });

    child.on("message", (msg: unknown) => {
      const m = msg as HostMessage;
      if (m?.type === "ready") {
        this.piVersion = typeof m.piVersion === "string" ? m.piVersion : null;
        appendMainLog(`agent-host ready pi=${this.piVersion ?? "unknown"}`);
        const restarted = this.wasReadyBeforeExit;
        this.wasReadyBeforeExit = false;
        this.postToolchainSnapshot("toolchain:init");
        this.postBrowserSnapshot("browser:init");
        this.postManagedProcessOwnerIdentity();
        this.setStatus("ready");
        this.startPing();
        if (restarted) {
          this.onHostMessage?.({ type: "host-restarted", reason: "crash-recovery" });
        }
      } else if (m?.type === "pong") {
        this.lastPong = Date.now();
      } else if (m?.type === "log") {
        appendMainLog(`[host] ${m.message}`);
      } else if (m?.type === "toolchain:ack") {
        const revision = Number(m.revision);
        if (Number.isSafeInteger(revision) && revision >= 0) {
          this.toolchainAckRevision = Math.max(this.toolchainAckRevision, revision);
          appendMainLog(`agent-host toolchain ack revision=${revision}`);
        }
      } else if (m?.type === "browser:ack") {
        const revision = Number(m.revision);
        if (Number.isSafeInteger(revision) && revision >= 0) {
          this.browserAckRevision = Math.max(this.browserAckRevision, revision);
          appendMainLog(`agent-host browser ack revision=${revision}`);
        }
      } else if (m?.type === "managed-process-owner:ack") {
        if (m.version === 1 && m.hostInstanceId === this.hostInstanceId && this.child === child) {
          this.managedProcessOwnerReady = true;
          appendMainLog("agent-host managed process owner identity acknowledged");
        }
      } else if (m?.type === "host-rpc") {
        const request = m as HostMessage & { id?: string; method?: string; params?: unknown };
        const id = String(request.id ?? "");
        const method = String(request.method ?? "");
        if (id && method) {
          void (async () => {
            try {
              if (!this.requestHandler) throw new Error("Main request handler is unavailable");
              const result = await this.requestHandler(method, request.params);
              try {
                child.postMessage({ type: "host-rpc-result", id, ok: true, result });
              } catch {
                /* child exited while the request was running */
              }
            } catch (error) {
              try {
                child.postMessage({
                  type: "host-rpc-result",
                  id,
                  ok: false,
                  error:
                    error instanceof BrowserError
                      ? error.toJSON()
                      : { message: error instanceof Error ? error.message : String(error) },
                });
              } catch {
                /* child exited while the request was running */
              }
            }
          })();
        }
      }
      this.onHostMessage?.(m);
    });

    child.on("exit", (code) => {
      appendMainLog(`agent-host exit code=${code}`);
      this.onHostMessage?.({ type: "host-exited", code });
      this.clearPing();
      const wasCurrentChild = this.child === child;
      if (wasCurrentChild) this.child = null;
      exitSignal.resolve();
      if (this.childExitSignal === exitSignal) this.childExitSignal = null;
      if (!wasCurrentChild) return;
      if (this.status === "stopped") return;

      this.wasReadyBeforeExit = this.status === "ready" || this.status === "starting";
      this.setStatus("starting", `Host exited (code ${code}); cleaning managed processes`);
      void (async () => {
        try {
          await this.beforeRestartHandler?.();
        } catch (error) {
          appendMainLog(
            `agent-host pre-restart cleanup failed: ${error instanceof Error ? error.message : String(error)}`,
          );
          this.setStatus("crashed", "Managed process cleanup could not be safely confirmed");
          return;
        }
        if (this.status === "stopped" || this.child) return;
        this.scheduleRestart(`Host exited (code ${code})`);
      })();
    });

    child.stdout?.on("data", (buf: Buffer) => stdoutBuffer.push(buf.toString()));
    child.stdout?.on("end", () => stdoutBuffer.flush());
    child.stderr?.on("data", (buf: Buffer) => stderrBuffer.push(buf.toString()));
    child.stderr?.on("end", () => stderrBuffer.flush());
  }

  private scheduleRestart(reason: string): void {
    if (this.status === "stopped") return;

    const reservation = reserveHostRestart(this.restartTimes, Date.now(), CRASH_WINDOW_MS, MAX_RESTARTS);
    this.restartTimes = reservation.restartTimes;
    if (reservation.attempt === null) {
      appendMainLog(`${reason}; restart budget exhausted`);
      this.setStatus("crashed", `${reason} and restart budget exhausted`);
      return;
    }

    appendMainLog(`restarting agent-host (attempt ${reservation.attempt}/${MAX_RESTARTS}): ${reason}`);
    this.setStatus("starting", `${reason}; restarting`);
    setTimeout(() => {
      if (this.status === "starting" && !this.child) this.spawn();
    }, 500).unref();
  }

  private startPing(): void {
    this.clearPing();
    this.lastPingTick = Date.now();
    this.pingTimer = setInterval(() => {
      if (!this.child) return;
      const now = Date.now();
      const heartbeat = evaluateHeartbeatTick({
        now,
        lastTickAt: this.lastPingTick,
        lastAcknowledgedAt: this.lastPong,
        intervalMs: PING_INTERVAL_MS,
        timeoutMs: PING_TIMEOUT_MS,
      });
      this.lastPingTick = now;
      if (heartbeat.clockDiscontinuity) this.lastPong = now;
      if (heartbeat.timedOut) {
        appendMainLog("agent-host ping timeout — killing");
        try {
          this.child.kill();
        } catch {
          /* ignore */
        }
        return;
      }
      try {
        this.child.postMessage({ type: "ping" });
      } catch {
        /* ignore */
      }
    }, PING_INTERVAL_MS);
  }

  private postToolchainSnapshot(type: "toolchain:init" | "toolchain:changed"): void {
    if (!this.child || !this.toolchainSnapshot) return;
    try {
      this.child.postMessage({ type, snapshot: this.toolchainSnapshot });
    } catch (error) {
      appendMainLog(`toolchain snapshot delivery failed: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  private postBrowserSnapshot(type: "browser:init" | "browser:changed"): void {
    if (!this.child || !this.browserCapabilitySnapshot) return;
    try {
      this.child.postMessage({ type, snapshot: this.browserCapabilitySnapshot });
    } catch (error) {
      appendMainLog(`browser snapshot delivery failed: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  private postManagedProcessOwnerIdentity(): void {
    if (!this.child || !this.hostInstanceId) return;
    const getCreationTime = (process as NodeJS.Process & { getCreationTime?: () => number | null }).getCreationTime;
    const creationTime = typeof getCreationTime === "function" ? getCreationTime.call(process) : null;
    if (typeof creationTime !== "number" || !Number.isSafeInteger(Math.trunc(creationTime)) || creationTime <= 0) {
      appendMainLog("managed process owner identity unavailable: main creation time missing");
      return;
    }
    try {
      this.child.postMessage({
        type: "managed-process-owner:init",
        version: 1,
        mainPid: process.pid,
        mainStartFingerprint: String(Math.trunc(creationTime)),
        mainImagePath: fs.realpathSync.native(process.execPath),
        hostInstanceId: this.hostInstanceId,
      });
    } catch {
      appendMainLog("managed process owner identity delivery failed");
    }
  }

  private clearPing(): void {
    if (this.pingTimer) {
      clearInterval(this.pingTimer);
      this.pingTimer = null;
    }
  }
}

export function resolveHostEntry(mainDirectory = __dirname): string {
  // ESM agent-host (pi packages are import-only)
  return path.join(mainDirectory, "agent-host.mjs");
}

export function resolvePreloadPath(mainDirectory = __dirname): string {
  return path.join(mainDirectory, "..", "preload", "preload.js");
}

export function resolveRendererEntry(isDev: boolean, mainDirectory = __dirname): string {
  // Explicit Vite URL (npm run dev sets this)
  if (process.env.VITE_DEV_SERVER_URL) {
    return process.env.VITE_DEV_SERVER_URL;
  }
  // Prefer built renderer whenever it exists (works for `npm start` after build)
  const builtIndex = path.join(mainDirectory, "..", "renderer", "index.html");
  if (fs.existsSync(builtIndex)) {
    return "app://bundle/index.html";
  }
  // Dev without prior build: expect Vite on 5173
  if (isDev) {
    return "http://localhost:5173";
  }
  return "app://bundle/index.html";
}

export function getUserDataPath(...parts: string[]): string {
  return path.join(app.getPath("userData"), ...parts);
}
export type HostSpawnResult<T> = { ok: true; child: T } | { ok: false; error: string };

export interface HostExitSignal {
  promise: Promise<void>;
  resolve: () => void;
}

export function createHostExitSignal(): HostExitSignal {
  let settled = false;
  let resolvePromise: () => void = () => undefined;
  const promise = new Promise<void>((resolve) => {
    resolvePromise = resolve;
  });
  return {
    promise,
    resolve: () => {
      if (settled) return;
      settled = true;
      resolvePromise();
    },
  };
}

export function trySpawnHost<T>(spawn: () => T): HostSpawnResult<T> {
  try {
    return { ok: true, child: spawn() };
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
}

export interface HostRestartReservation {
  restartTimes: number[];
  attempt: number | null;
}

export function reserveHostRestart(
  restartTimes: readonly number[],
  now: number,
  crashWindowMs: number,
  maxRestarts: number,
): HostRestartReservation {
  const recentRestartTimes = restartTimes.filter((time) => now - time < crashWindowMs);
  if (recentRestartTimes.length >= maxRestarts) {
    return { restartTimes: recentRestartTimes, attempt: null };
  }
  recentRestartTimes.push(now);
  return { restartTimes: recentRestartTimes, attempt: recentRestartTimes.length };
}

import { randomUUID } from "node:crypto";
import type {
  BrowserAdvancedRuntimePolicy,
  BrowserCapabilityLease,
  BrowserCapabilitySnapshot,
  BrowserHostRequestContext,
  BrowserPermissionLevel,
  BrowserSessionGrantInput,
  BrowserSettingsV2,
} from "../../contract/browser.ts";
import { BrowserError } from "./browser-error.ts";

const PERMISSION_RANK: Record<BrowserPermissionLevel, number> = {
  none: 0,
  read: 1,
  interact: 2,
  advanced: 3,
};
const DEFAULT_GRANT_TTL_MS = 8 * 60 * 60 * 1_000;
const DEFAULT_LEASE_TTL_MS = 15 * 60 * 1_000;

type SessionGrant = BrowserSessionGrantInput & { expiresAt: number };

export interface BrowserPolicyEngineOptions {
  now?: () => number;
  createId?: () => string;
  grantTtlMs?: number;
  leaseTtlMs?: number;
}

export class BrowserPolicyEngine {
  private revision = 0;
  private settings: BrowserSettingsV2;
  private readonly grants = new Map<string, SessionGrant>();
  private readonly leases = new Map<string, BrowserCapabilityLease>();
  private readonly listeners = new Set<(snapshot: BrowserCapabilitySnapshot) => void>();
  private readonly now: () => number;
  private readonly createId: () => string;
  private readonly grantTtlMs: number;
  private readonly leaseTtlMs: number;

  constructor(settings: BrowserSettingsV2, options: BrowserPolicyEngineOptions = {}) {
    this.settings = structuredClone(settings);
    this.now = options.now ?? Date.now;
    this.createId = options.createId ?? randomUUID;
    this.grantTtlMs = options.grantTtlMs ?? DEFAULT_GRANT_TTL_MS;
    this.leaseTtlMs = options.leaseTtlMs ?? DEFAULT_LEASE_TTL_MS;
  }

  subscribe(listener: (snapshot: BrowserCapabilitySnapshot) => void): () => void {
    this.listeners.add(listener);
    listener(this.getSnapshot());
    return () => this.listeners.delete(listener);
  }

  getRevision(): number {
    return this.revision;
  }

  getSettings(): BrowserSettingsV2 {
    return structuredClone(this.settings);
  }

  getAdvancedRuntimePolicy(): BrowserAdvancedRuntimePolicy {
    const advanced = this.settings.advancedBrowserMode;
    if (!advanced.enabled) return createDisabledAdvancedRuntimePolicy();
    return {
      enabled: true,
      removeSiteSecurityHeaders: true,
      disableWebSecurity: true,
      allowInsecureContent: true,
      certificateBypassDomains: [...advanced.certificateBypassDomains],
      unrestrictedRawCdp: true,
    };
  }

  isAdvancedEnabled(): boolean {
    return this.settings.advancedBrowserMode.enabled;
  }

  isHighRiskPermissionEnabled(): boolean {
    return this.isAdvancedEnabled();
  }

  updateSettings(settings: BrowserSettingsV2): BrowserCapabilitySnapshot {
    this.settings = structuredClone(settings);
    if (!settings.enabled || !settings.automation.enabled) this.grants.clear();
    if (!settings.advancedBrowserMode.enabled) this.downgradeAdvancedGrants();
    this.bumpRevision();
    return this.getSnapshot();
  }

  grantSession(input: BrowserSessionGrantInput): BrowserCapabilityLease | undefined {
    const sessionId = validateSessionId(input.sessionId);
    if (!this.settings.enabled) throw new BrowserError("BROWSER_DISABLED", "The built-in browser is disabled");
    if (!this.settings.automation.enabled) {
      throw new BrowserError("CAPABILITY_DISABLED", "Agent browser tools are disabled");
    }
    if (input.source === "channel" && !this.settings.automation.allowChannelSessions) {
      throw new BrowserError("CAPABILITY_DISABLED", "Browser access for channel sessions is disabled");
    }
    if (input.permission === "advanced") {
      if (!this.isHighRiskPermissionEnabled()) {
        throw new BrowserError("ADVANCED_CONFIRMATION_REQUIRED", "Advanced browser capabilities are disabled");
      }
    }
    const requestedTtl = input.expiresInMs ?? this.grantTtlMs;
    const ttl = Math.max(1_000, Math.min(requestedTtl, this.grantTtlMs));
    this.grants.set(sessionId, { ...input, sessionId, expiresAt: this.now() + ttl });
    this.bumpRevision();
    return input.permission === "none" ? undefined : this.issueLease(sessionId);
  }

  revokeSession(sessionId: string): BrowserCapabilitySnapshot {
    const normalized = validateSessionId(sessionId);
    this.grants.delete(normalized);
    for (const [id, lease] of this.leases) {
      if (lease.sessionId === normalized) this.leases.delete(id);
    }
    this.bumpRevision();
    return this.getSnapshot();
  }

  revokeAll(): BrowserCapabilitySnapshot {
    this.grants.clear();
    this.bumpRevision();
    return this.getSnapshot();
  }

  issueLease(sessionId: string): BrowserCapabilityLease {
    this.pruneExpired();
    const normalized = validateSessionId(sessionId);
    const grant = this.grants.get(normalized);
    if (!grant || grant.permission === "none") {
      throw new BrowserError("CAPABILITY_DISABLED", "This session has no Browser permission");
    }
    if (grant.permission === "advanced" && !this.isHighRiskPermissionEnabled()) {
      throw new BrowserError("CAPABILITY_DISABLED", "Advanced Browser permission is no longer enabled");
    }
    const lease: BrowserCapabilityLease = {
      id: this.createId(),
      sessionId: normalized,
      permission: grant.permission,
      policyRevision: this.revision,
      expiresAt: Math.min(grant.expiresAt, this.now() + this.leaseTtlMs),
    };
    this.leases.set(lease.id, lease);
    return structuredClone(lease);
  }

  getLeaseForSession(sessionId: string): BrowserCapabilityLease | undefined {
    this.pruneExpired();
    const normalized = validateSessionId(sessionId);
    const lease = [...this.leases.values()]
      .filter((candidate) => candidate.sessionId === normalized && candidate.policyRevision === this.revision)
      .sort((left, right) => right.expiresAt - left.expiresAt)[0];
    return lease ? structuredClone(lease) : undefined;
  }

  assertRequest(context: BrowserHostRequestContext, required: BrowserPermissionLevel): BrowserCapabilityLease {
    this.pruneExpired();
    if (!this.settings.enabled) throw new BrowserError("BROWSER_DISABLED", "The built-in browser is disabled");
    if (!this.settings.automation.enabled) {
      throw new BrowserError("CAPABILITY_DISABLED", "Agent browser tools are disabled");
    }
    if (!context.requestId || context.requestId.length > 256 || /[\0\r\n]/.test(context.requestId)) {
      throw new BrowserError("INVALID_BROWSER_REQUEST", "Browser requestId is invalid");
    }
    if (context.policyRevision !== this.revision) {
      throw new BrowserError("POLICY_REVISION_MISMATCH", "Browser policy changed; refresh capabilities", {
        retryable: true,
        details: { expectedRevision: this.revision },
      });
    }
    const lease = this.leases.get(context.capabilityLeaseId);
    if (!lease || lease.expiresAt <= this.now()) {
      throw new BrowserError("CAPABILITY_LEASE_EXPIRED", "Browser capability lease expired", { retryable: true });
    }
    if (lease.policyRevision !== this.revision || lease.sessionId !== context.sessionId) {
      throw new BrowserError("CAPABILITY_LEASE_EXPIRED", "Browser capability lease is no longer valid", {
        retryable: true,
      });
    }
    if (PERMISSION_RANK[lease.permission] < PERMISSION_RANK[required]) {
      throw new BrowserError("CAPABILITY_DISABLED", `Browser ${required} permission is required`);
    }
    if (required === "advanced" && !this.isHighRiskPermissionEnabled()) {
      throw new BrowserError("ADVANCED_CONFIRMATION_REQUIRED", "Advanced browser capabilities are disabled");
    }
    return structuredClone(lease);
  }

  getSnapshot(): BrowserCapabilitySnapshot {
    this.pruneExpired();
    const sessionPermissions: Record<string, BrowserPermissionLevel> = {};
    for (const [sessionId, grant] of this.grants) sessionPermissions[sessionId] = grant.permission;
    return {
      revision: this.revision,
      browserEnabled: this.settings.enabled,
      automationEnabled: this.settings.automation.enabled,
      advancedEnabled: this.isHighRiskPermissionEnabled(),
      sessionPermissions,
      generatedAt: this.now(),
    };
  }

  private bumpRevision(): void {
    this.revision++;
    this.leases.clear();
    const snapshot = this.getSnapshot();
    for (const listener of this.listeners) listener(snapshot);
  }

  private pruneExpired(): void {
    const now = this.now();
    for (const [sessionId, grant] of this.grants) {
      if (grant.expiresAt <= now) this.grants.delete(sessionId);
    }
    for (const [id, lease] of this.leases) {
      if (lease.expiresAt <= now) this.leases.delete(id);
    }
  }

  private downgradeAdvancedGrants(): void {
    for (const [sessionId, grant] of this.grants) {
      if (grant.permission === "advanced") this.grants.set(sessionId, { ...grant, permission: "interact" });
    }
  }
}

export function createDisabledAdvancedRuntimePolicy(): BrowserAdvancedRuntimePolicy {
  return {
    enabled: false,
    removeSiteSecurityHeaders: false,
    disableWebSecurity: false,
    allowInsecureContent: false,
    certificateBypassDomains: [],
    unrestrictedRawCdp: false,
  };
}

function validateSessionId(sessionId: string): string {
  const normalized = sessionId.trim();
  if (!normalized || normalized.length > 256 || /[\0\r\n]/.test(normalized)) {
    throw new BrowserError("INVALID_BROWSER_REQUEST", "Browser sessionId is invalid");
  }
  return normalized;
}
