async function stopAllManagedProcessesFromTray(): Promise<void> {
  if (runningManagedProcessCount <= 0 || hostManager?.getStatus() !== "ready") return;
  const window = getMainWindow();
  const copy = managedProcessDialogCopy();
  const options = {
    type: "warning" as const,
    title: copy.stopAllTitle,
    message: copy.stopAllMessage(runningManagedProcessCount),
    detail: copy.stopAllDetail,
    buttons: [copy.stopAllButton, copy.cancelButton],
    defaultId: 1,
    cancelId: 1,
    noLink: true,
  };
  const result = window ? await dialog.showMessageBox(window, options) : await dialog.showMessageBox(options);
  if (result.response !== 0) return;
  try {
    await hostManager.call("processes.stopAll", { mode: "graceful" }, 15_000);
  } catch (error) {
    appendMainLog(`stop all managed processes failed: ${error instanceof Error ? error.message : String(error)}`);
  }
}

function applyBadgeCount(count: number): void {
  unreadBadge = Math.max(0, Number(count) || 0);
  if (process.platform === "win32") {
    const win = getMainWindow();
    if (!win || win.isDestroyed()) return;
    if (unreadBadge === 0) {
      win.setOverlayIcon(null, "No unread completed sessions");
      return;
    }
    const overlay = nativeImage
      .createFromPath(path.join(app.getAppPath(), "build", "icon.png"))
      .resize({ width: 16, height: 16 });
    win.setOverlayIcon(overlay, `${unreadBadge} unread completed session${unreadBadge === 1 ? "" : "s"}`);
    return;
  }
  app.setBadgeCount(unreadBadge);
}

function handleDeepLink(url: string): void {
  const parsed = parseDesktopDeepLink(url);
  appendMainLog(`deep link received valid=${Boolean(parsed?.sessionId)}`);
  if (!parsed?.sessionId) return;
  const win = getMainWindow();
  if (win) {
    win.webContents.send("deep-link:session", parsed.sessionId);
    win.show();
    win.focus();
  } else {
    pendingDeepLink = parsed.sessionId;
  }
}

function startMainProcess(): void {
  if (
    !acquireSingleInstanceLock(getMainWindow, (argv) => {
      const url = findDesktopDeepLink(argv);
      if (url) handleDeepLink(url);
    })
  ) {
    app.quit();
    return;
  }

  app.on("open-url", (event, url) => {
    event.preventDefault();
    handleDeepLink(url);
  });

  app.on("login", (event, webContents, _details, authInfo, callback) => {
    const credentials = browserService?.getProxyCredentialsForWebContents(webContents.id, authInfo.isProxy);
    if (!credentials) return;
    event.preventDefault();
    callback(credentials.username, credentials.password);
  });

  function createWindow(): BrowserWindow {
    const win = createMainWindow({
      isDev,
      consumePendingDeepLink: () => {
        const sessionId = pendingDeepLink;
        pendingDeepLink = null;
        return sessionId;
      },
      shouldHideOnClose: () => !isQuitting && loadUiState().backgroundMode !== false,
      onClosed: (closedWindow) => {
        if (mainWindow === closedWindow) {
          mainWindow = null;
          browserService?.handleWindowClosed();
        }
      },
      onRendererUnavailable: () => browserService?.handleRendererUnavailable(),
    });
    mainWindow = win;
    win.on("hide", () => browserService?.handleWindowVisibility(false));
    win.on("minimize", () => browserService?.handleWindowVisibility(false));
    win.on("show", () => browserService?.handleWindowVisibility(true));
    win.on("restore", () => browserService?.handleWindowVisibility(true));
    win.on("focus", () => {
      const manager = toolchainManager;
      const now = Date.now();
      if (!manager || now - lastToolchainFocusScanAt < TOOLCHAIN_FOCUS_RESCAN_TTL_MS) return;
      lastToolchainFocusScanAt = now;
      void manager.rescan().catch((error) => {
        appendMainLog(`toolchain focus rescan failed: ${error instanceof Error ? error.message : String(error)}`);
      });
    });
    if (packagedStartupValidation) {
      win.webContents.once("did-finish-load", () => {
        startupRendererReady = true;
        finishPackagedStartupValidation();
      });
      win.webContents.once("did-fail-load", (_event, code, description) => {
        finishPackagedStartupValidation(`Renderer failed to load (${code}): ${description}`);
      });
    }
    if (unreadBadge > 0) applyBadgeCount(unreadBadge);
    void browserService?.restoreTabs();
    return win;
  }

  function openUpdateSettings(checkForUpdates: boolean): void {
    const win = getMainWindow() ?? createWindow();
    win.show();
    win.focus();
    const send = () => {
      if (!win.isDestroyed()) {
        win.webContents.send(checkForUpdates ? "menu:check-for-updates" : "menu:show-update");
      }
    };
    if (win.webContents.isLoadingMainFrame()) {
      win.webContents.once("did-finish-load", send);
    } else {
      send();
    }
  }

  void app.whenReady().then(async () => {
    appendMainLog(`app ready packaged=${app.isPackaged}`);
    if (packagedCleanupFaultValidation) {
      let exitCode = 0;
      try {
        const report = await runPackagedCleanupFaultValidation({
          productionDeadlineMs: MANAGED_PROCESS_SHUTDOWN_DEADLINE_MS,
        });
        fs.mkdirSync(app.getPath("userData"), { recursive: true, mode: 0o700 });
        fs.writeFileSync(
          path.join(app.getPath("userData"), "packaged-cleanup-fault-check.json"),
          `${JSON.stringify(report, null, 2)}\n`,
          { encoding: "utf8", mode: 0o600 },
        );
        if (!report.ok) exitCode = 1;
      } catch (error) {
        exitCode = 1;
        appendMainLog(`packaged cleanup fault validation failed: ${error instanceof Error ? error.name : "unknown"}`);
      }
      isQuitting = true;
      quitCleanupComplete = true;
      app.exit(exitCode);
      return;
    }
    if (process.platform === "win32" && process.arch === "x64") {
      windowsManagedProcessHelper = resolveWindowsManagedProcessHelper({
        isPackaged: app.isPackaged,
        resourcesPath: process.resourcesPath,
        projectRoot: path.resolve(__dirname, "../.."),
      });
      appendMainLog(
        windowsManagedProcessHelper.ok
          ? `windows managed process helper verified build=${windowsManagedProcessHelper.descriptor.buildId} provenance=${windowsManagedProcessHelper.descriptor.provenance}`
          : `windows managed process helper unavailable error=${windowsManagedProcessHelper.errorCode}`,
      );
    }
    const reaperDirectory = path.join(app.getPath("userData"), "managed-process-reaper");
    const windowsJournalSecured =
      process.platform !== "win32" ||
      Boolean(
        windowsManagedProcessHelper?.ok &&
        (await secureWindowsReaperDirectory(reaperDirectory, windowsManagedProcessHelper.descriptor, appendMainLog)),
      );
    managedProcessReaper = new ManagedProcessReaper(path.join(reaperDirectory, "journal-v2.json"), {
      log: appendMainLog,
      ...(windowsManagedProcessHelper?.ok && windowsJournalSecured
        ? { windowsHelper: windowsManagedProcessHelper.descriptor }
        : {}),
    });
    const reaperStatus = await managedProcessReaper.initialize();
    appendMainLog(
      `managed process reaper ready=${reaperStatus.ready} records=${reaperStatus.records} revision=${reaperStatus.revision}${reaperStatus.errorCode ? ` error=${reaperStatus.errorCode}` : ""}`,
    );
    if (packagedStartupValidation) {
      startupCheckTimer = setTimeout(
        () => finishPackagedStartupValidation("Packaged startup validation timed out"),
        45_000,
      );
    }

    const credentialVault = new CredentialVault(getUserDataPath("channels.secrets.json"));
    browserService = new BrowserService({
      userDataDir: app.getPath("userData"),
      getWindow: getMainWindow,
      emit: (event) => {
        const win = getMainWindow();
        if (win && !win.isDestroyed()) win.webContents.send("browser:event", event);
      },
      onCapabilitySnapshot: (snapshot) => hostManager?.setBrowserCapabilitySnapshot(snapshot),
    });
    const ui = loadUiState();
    const updaterTestMode = !app.isPackaged && process.env.PI_DESKTOP_TEST_UPDATER === "1";
    const updaterSupported =
      isProductionUpdatePlatformEnabled(process.platform) ||
      (updaterTestMode && (process.platform === "darwin" || process.platform === "win32"));
    const updaterRequested = app.isPackaged || updaterTestMode;
    let updateAdapter = null;
    if (updaterSupported && updaterRequested) {
      try {
        updateAdapter = await createProductionUpdateAdapter({
          useDevelopmentConfig: updaterTestMode,
        });
      } catch (error) {
        appendMainLog(`updater unavailable: ${redactUpdateError(error)}`);
      }
    }
    updateManager = createUpdateManager({
      adapter: updateAdapter,
      currentVersion: app.getVersion(),
      isPackaged: app.isPackaged,
      automaticChecksEnabled: ui.automaticUpdateChecks !== false,
      prepareToInstall: async () => {
        isQuitting = true;
        destroyTray();
        const deadline = Date.now() + MANAGED_PROCESS_SHUTDOWN_DEADLINE_MS;
        await cleanupManagedProcesses(deadline, true);
        if (process.platform === "win32") {
          const refreshed = resolveWindowsManagedProcessHelper({
            isPackaged: app.isPackaged,
            resourcesPath: process.resourcesPath,
            projectRoot: path.resolve(__dirname, "../.."),
          });
          if (!refreshed.ok) throw new Error("Windows managed process helper is unavailable for update");
          if (!verifyWindowsManagedProcessHelperReplaceable(refreshed.descriptor)) {
            throw new Error("Windows managed process helper is locked for update");
          }
          windowsManagedProcessHelper = refreshed;
        }
      },
      recoverFromInstallFailure: async () => {
        isQuitting = false;
        createTray(getMainWindow, () => void stopAllManagedProcessesFromTray());
        const manager = hostManager;
        if (manager) await restartHostAfterExit(manager, () => !isQuitting);
      },
      log: (level, message) => appendMainLog(`updater[${level}] ${message}`),
    });
    const bundledCorePaths = resolveBundledCorePaths({
      isPackaged: app.isPackaged,
      resourcesRoot: process.resourcesPath,
    });
    const toolchainHome = app.getPath("home");
    toolchainManager = new ToolchainManager({
      platform: process.platform,
      arch: process.arch,
      env: process.env,
      homeDir: toolchainHome,
      tempRoot: app.getPath("temp"),
      userDataRoot: app.getPath("userData"),
      resourcesRoot: process.resourcesPath,
      catalogPath: resolveRuntimeCatalogPath({
        isPackaged: app.isPackaged,
        resourcesRoot: process.resourcesPath,
      }),
      coreCatalogPath: bundledCorePaths.catalogPath,
      bundledCoreRoot: bundledCorePaths.coreRoot,
      // Chromium networking follows the user's system proxy/PAC and OS trust
      // configuration. Redirects are synchronously allowlisted before following.
      fetchImpl: createElectronRuntimeFetch((options) => net.request(options)),
      legacyNpmCommand: readLegacyNpmCommand({ homeDir: toolchainHome, env: process.env }),
      isRuntimeInUse: () => runningAgentSessionCount > 0,
    });
    toolchainManager.subscribe((snapshot) => {
      if (packagedStartupValidation) startupToolchainSnapshot = snapshot;
      appendMainLog(
        `toolchain scan revision=${snapshot.revision} candidates=${snapshot.candidates.length} ready=${snapshot.publicState.coreReady}`,
      );
      for (const win of BrowserWindow.getAllWindows()) {
        if (!win.isDestroyed()) win.webContents.send("toolchains:state", snapshot.publicState);
      }
      hostManager?.setToolchainSnapshot(snapshot);
      finishPackagedStartupValidation();
    });
    updateManager.subscribe((state) => {
      for (const win of BrowserWindow.getAllWindows()) {
        if (!win.isDestroyed()) win.webContents.send("update:state", state);
      }
      if (state.phase === "available") {
        const notificationKey = state.availableVersion ?? "unknown";
        if (lastNotifiedUpdateVersion !== notificationKey) {
          lastNotifiedUpdateVersion = notificationKey;
          const win = getMainWindow();
          const shouldNotify = !win || !win.isVisible() || !win.isFocused();
          if (shouldNotify && Notification.isSupported()) {
            const notification = new Notification({
              title: "Pi Agent Desktop update available",
              body: state.availableVersion
                ? `Version ${state.availableVersion} is ready to download.`
                : "A new version is ready to download.",
            });
            notification.on("click", () => {
              openUpdateSettings(false);
            });
            notification.show();
          }
        }
      }
    });

    // Always register app:// so we can load the built renderer without Vite
    // (npm start after build, or dev fallback when VITE_DEV_SERVER_URL is unset).
    handleAppProtocol(rendererRootPath());

    installDesktopIpc({
      getHostManager: () => hostManager,
      getMainWindow,
      getUnreadBadge: () => unreadBadge,
      applyBadgeCount,
      getToolchainState: (cwd) =>
        cwd ? toolchainManager!.getPublicStateForProject(cwd) : toolchainManager!.getPublicState(),
      rescanToolchains: async (cwd) => {
        await toolchainManager!.rescan({ cwd });
        return cwd ? toolchainManager!.getPublicStateForProject(cwd) : toolchainManager!.getPublicState();
      },
      performToolchainAction: (request) => toolchainManager!.performAction(request),
      chooseCustomTool: (capability, executable) => toolchainManager!.registerCustomTool(capability, executable),
      setChannelCredential: (payload) =>
        credentialVault.set(`channel:${payload.channel}:${payload.accountId}`, payload.credential),
      getBrowserService: () => browserService,
      getManagedProcessCapability,
      updateManager,
    });
    installAppMenu(getMainWindow, () => openUpdateSettings(true), isDev);

    createTray(getMainWindow, () => void stopAllManagedProcessesFromTray());

    // Apply persisted theme preference
    if (ui.theme === "light" || ui.theme === "dark" || ui.theme === "system") {
      nativeTheme.themeSource = ui.theme;
    }

    hostManager = new HostManager(resolveHostEntry());
    hostManager.setBeforeRestartHandler(async () => {
      const status = await managedProcessReaper!.reapAll();
      appendMainLog(
        `managed process pre-restart reap ready=${status.ready} records=${status.records}${status.errorCode ? ` error=${status.errorCode}` : ""}`,
      );
      if (!status.ready || status.records !== 0) {
        throw new Error(`Managed process cleanup blocked Host restart (${status.errorCode ?? "unknown"})`);
      }
    });
    hostManager.setToolchainSnapshot(toolchainManager.getSnapshot());
    hostManager.setBrowserCapabilitySnapshot(browserService.getCapabilitySnapshot());
    const credentialRequestHandler = createCredentialRequestHandler(credentialVault);
    hostManager.setRequestHandler(async (method, params) => {
      if (method.startsWith("channelSecrets.")) return credentialRequestHandler(method, params);
      if (method === "toolchain.getSnapshot") return toolchainManager!.getSnapshot();
      if (method === "toolchain.resolve") {
        const body = (params ?? {}) as { cwd?: unknown; intent?: unknown; trusted?: unknown };
        if (
          typeof body.cwd !== "string" ||
          !path.isAbsolute(body.cwd) ||
          body.cwd.length > 4_096 ||
          /[\0\r\n]/.test(body.cwd) ||
          !isExecutionIntent(body.intent) ||
          typeof body.trusted !== "boolean"
        ) {
          throw new Error("Invalid Host toolchain resolution request");
        }
        return toolchainManager!.resolveForProject(body.cwd, { intent: body.intent, trusted: body.trusted });
      }
      if (method === "managedProcesses.getSettings") {
        const status = managedProcessReaper?.status();
        const capability = getManagedProcessCapability();
        return {
          enabled: capability.ready && loadUiState().managedProcessesEnabled === true,
          reaperReady: status?.ready === true,
          capability,
          ...(windowsManagedProcessHelper?.ok ? { windowsHelper: windowsManagedProcessHelper.descriptor } : {}),
        };
      }
      if (method === "managedProcesses.register") {
        const body = (params ?? {}) as { record?: unknown };
        const record = body.record;
        const recordPlatform =
          record && typeof record === "object" && !Array.isArray(record)
            ? (record as { platform?: unknown }).platform
            : undefined;
        if (recordPlatform === "win32") {
          const currentOwner = hostManager?.getManagedProcessOwnerState();
          const recordOwner = (record as { hostInstanceId?: unknown }).hostInstanceId;
          if (!currentOwner?.ready || recordOwner !== currentOwner.hostInstanceId) {
            throw new Error("Windows managed process register owner generation mismatch");
          }
        }
        return managedProcessReaper!.register(record);
      }
      if (method === "managedProcesses.unregister") {
        return managedProcessReaper!.unregister(params);
      }
      if (method === "managedProcesses.confirmLanBind") {
        const body = (params ?? {}) as { ownerSessionId?: unknown; commandHash?: unknown };
        if (
          typeof body.ownerSessionId !== "string" ||
          body.ownerSessionId.length > 128 ||
          typeof body.commandHash !== "string" ||
          !/^[a-f0-9]{16}$/.test(body.commandHash)
        ) {
          throw new Error("Invalid managed process network confirmation request");
        }
        const window = getMainWindow();
        const copy = managedProcessDialogCopy();
        const options = {
          type: "warning" as const,
          title: copy.lanTitle,
          message: copy.lanMessage,
          detail: copy.lanDetail,
          buttons: [copy.allowOnceButton, copy.cancelButton],
          defaultId: 1,
          cancelId: 1,
          noLink: true,
        };
        const result = window ? await dialog.showMessageBox(window, options) : await dialog.showMessageBox(options);
        return { confirmed: result.response === 0 };
      }
      if (method === "managedProcesses.selectExportTarget") {
        const body = (params ?? {}) as { suggestedName?: unknown };
        const suggestedName =
          typeof body.suggestedName === "string" && /^[a-z0-9._-]{1,128}$/i.test(body.suggestedName)
            ? body.suggestedName
            : "managed-process.log";
        const copy = managedProcessDialogCopy();
        const options = {
          title: copy.exportTitle,
          defaultPath: suggestedName,
          filters: [{ name: copy.exportFilter, extensions: ["log", "txt"] }],
          properties: ["showOverwriteConfirmation" as const, "createDirectory" as const],
        };
        const window = getMainWindow();
        const result = window ? await dialog.showSaveDialog(window, options) : await dialog.showSaveDialog(options);
        return result.canceled || !result.filePath
          ? {}
          : { path: result.filePath, fileName: path.basename(result.filePath) };
      }
      if (method.startsWith("browser.")) {
        return browserService!.handleHostRequest(method, params);
      }
      throw new Error(`Unsupported Host request: ${method}`);
    });
    hostManager.setStatusListener((status, detail) => {
      appendMainLog(`host status=${status} ${detail ?? ""}`);
      if (packagedStartupValidation) {
        startupHostReady = status === "ready";
        if (status === "crashed") finishPackagedStartupValidation(detail ?? "Agent Host crashed");
        else finishPackagedStartupValidation();
      }
      if (status !== "ready") {
        runningAgentSessionCount = 0;
        runningManagedProcessCount = 0;
        setTrayRunningCount(0, getMainWindow);
        setTrayManagedProcessCount(0, getMainWindow);
        updateManager?.setRunningSessionCount(0);
        browserService?.onHostStopped();
      }
      for (const win of BrowserWindow.getAllWindows()) {
        win.webContents.send("host:status", { status, detail });
        if (status === "ready" && detail?.includes("restart")) {
          win.webContents.send("host:restarted", { reason: detail });
        }
        if (status === "crashed") {
          win.webContents.send("host:crashed", { detail });
        }
      }
    });

    hostManager.setMessageListener((msg) => {
      if (packagedStartupValidation && msg.type === "toolchain:ack") finishPackagedStartupValidation();
      if (msg.type === "running-sessions") {
        const ids = (msg.sessionIds as string[]) ?? [];
        runningAgentSessionCount = ids.length;
        setTrayRunningCount(ids.length, getMainWindow);
        updateManager?.setRunningSessionCount(ids.length);
      } else if (msg.type === "managed-process-count") {
        const count = Number(msg.count);
        runningManagedProcessCount = Number.isSafeInteger(count) && count >= 0 ? count : 0;
        setTrayManagedProcessCount(runningManagedProcessCount, getMainWindow);
      } else if (msg.type === "agent-end") {
        const sessionId = String(msg.sessionId ?? "");
        // Notify if no focused window or window is hidden (desktop value-add)
        const win = getMainWindow();
        const shouldNotify = !win || !win.isVisible() || !win.isFocused();
        if (shouldNotify && Notification.isSupported() && sessionId) {
          const n = new Notification({
            title: "Agent finished",
            body: "A session completed in the background",
          });
          n.on("click", () => {
            const w = getMainWindow();
            if (w) {
              w.show();
              w.focus();
              w.webContents.send("deep-link:session", sessionId);
            }
          });
          n.show();
          applyBadgeCount(unreadBadge + 1);
        }
      } else if (msg.type === "host-restarted") {
        for (const win of BrowserWindow.getAllWindows()) {
          win.webContents.send("host:restarted", { reason: String(msg.reason ?? "restart") });
        }
      }
    });

    hostManager.start();

    createWindow();
    void toolchainManager.initialize();
    updateManager.startAutomaticChecks();

    app.on("activate", () => {
      if (BrowserWindow.getAllWindows().length === 0) {
        createWindow();
      } else {
        getMainWindow()?.show();
      }
    });
  });

  app.on("before-quit", (event) => {
    if (quitCleanupComplete) return;
    event.preventDefault();
    if (quitCleanupStarted) return;
    quitCleanupStarted = true;
    void (async () => {
      if (runningManagedProcessCount > 0 && !packagedStartupValidation) {
        const window = getMainWindow();
        const copy = managedProcessDialogCopy();
        const options = {
          type: "warning" as const,
          title: copy.quitTitle,
          message: copy.quitMessage(runningManagedProcessCount),
          detail: copy.quitDetail,
          buttons: [copy.stopAndQuitButton, copy.cancelButton],
          defaultId: 0,
          cancelId: 1,
          noLink: true,
        };
        const result = window ? await dialog.showMessageBox(window, options) : await dialog.showMessageBox(options);
        if (result.response !== 0) {
          quitCleanupStarted = false;
          isQuitting = false;
          return;
        }
      }
      isQuitting = true;
      updateManager?.stopAutomaticChecks();
      destroyTray();
      const deadline = Date.now() + MANAGED_PROCESS_SHUTDOWN_DEADLINE_MS;
      try {
        await cleanupManagedProcesses(deadline, false);
        const browserCleanup = await beforeDeadline(browserService?.dispose() ?? Promise.resolve(), deadline);
        if (!browserCleanup.completed) appendMainLog("browser cleanup reached the shutdown deadline");
      } catch (error) {
        appendMainLog(`quit cleanup failed: ${error instanceof Error ? error.message : String(error)}`);
      } finally {
        quitCleanupComplete = true;
        app.quit();
      }
    })();
  });

  app.on("certificate-error", (event, webContents, url, _error, _certificate, callback) => {
    try {
      const hostname = new URL(url).hostname;
      if (browserService?.handleCertificateError(webContents.id, hostname)) {
        event.preventDefault();
        callback(true);
      }
    } catch {
      // Chromium's default certificate policy remains in force.
    }
  });

  app.on("window-all-closed", () => {
    if (process.platform !== "darwin") {
      app.quit();
    }
  });

  // Deep link registration
  if (process.defaultApp) {
    if (process.argv.length >= 2) {
      app.setAsDefaultProtocolClient("pi-agent-desktop", process.execPath, [path.resolve(process.argv[1])]);
    }
  } else {
    app.setAsDefaultProtocolClient("pi-agent-desktop");
  }
}

startMainProcess();

import { randomUUID } from "node:crypto";
import type {
  BrowserAdvancedRuntimePolicy,
  BrowserCapabilityLease,
  BrowserCapabilitySnapshot,
  BrowserHostRequestContext,
  BrowserPermissionLevel,
  BrowserSessionGrantInput,
  BrowserSettingsV2,
} from "../../contract/browser.ts";
import { BrowserError } from "./browser-error.ts";

const PERMISSION_RANK: Record<BrowserPermissionLevel, number> = {
  none: 0,
  read: 1,
  interact: 2,
  advanced: 3,
};
const DEFAULT_GRANT_TTL_MS = 8 * 60 * 60 * 1_000;
const DEFAULT_LEASE_TTL_MS = 15 * 60 * 1_000;

type SessionGrant = BrowserSessionGrantInput & { expiresAt: number };

export interface BrowserPolicyEngineOptions {
  now?: () => number;
  createId?: () => string;
  grantTtlMs?: number;
  leaseTtlMs?: number;
}

export class BrowserPolicyEngine {
  private revision = 0;
  private settings: BrowserSettingsV2;
  private readonly grants = new Map<string, SessionGrant>();
  private readonly leases = new Map<string, BrowserCapabilityLease>();
  private readonly listeners = new Set<(snapshot: BrowserCapabilitySnapshot) => void>();
  private readonly now: () => number;
  private readonly createId: () => string;
  private readonly grantTtlMs: number;
  private readonly leaseTtlMs: number;

  constructor(settings: BrowserSettingsV2, options: BrowserPolicyEngineOptions = {}) {
    this.settings = structuredClone(settings);
    this.now = options.now ?? Date.now;
    this.createId = options.createId ?? randomUUID;
    this.grantTtlMs = options.grantTtlMs ?? DEFAULT_GRANT_TTL_MS;
    this.leaseTtlMs = options.leaseTtlMs ?? DEFAULT_LEASE_TTL_MS;
  }

  subscribe(listener: (snapshot: BrowserCapabilitySnapshot) => void): () => void {
    this.listeners.add(listener);
    listener(this.getSnapshot());
    return () => this.listeners.delete(listener);
  }

  getRevision(): number {
    return this.revision;
  }

  getSettings(): BrowserSettingsV2 {
    return structuredClone(this.settings);
  }

  getAdvancedRuntimePolicy(): BrowserAdvancedRuntimePolicy {
    const advanced = this.settings.advancedBrowserMode;
    if (!advanced.enabled) return createDisabledAdvancedRuntimePolicy();
    return {
      enabled: true,
      removeSiteSecurityHeaders: true,
      disableWebSecurity: true,
      allowInsecureContent: true,
      certificateBypassDomains: [...advanced.certificateBypassDomains],
      unrestrictedRawCdp: true,
    };
  }

  isAdvancedEnabled(): boolean {
    return this.settings.advancedBrowserMode.enabled;
  }

  isHighRiskPermissionEnabled(): boolean {
    return this.isAdvancedEnabled();
  }

  updateSettings(settings: BrowserSettingsV2): BrowserCapabilitySnapshot {
    this.settings = structuredClone(settings);
    if (!settings.enabled || !settings.automation.enabled) this.grants.clear();
    if (!settings.advancedBrowserMode.enabled) this.downgradeAdvancedGrants();
    this.bumpRevision();
    return this.getSnapshot();
  }

  grantSession(input: BrowserSessionGrantInput): BrowserCapabilityLease | undefined {
    const sessionId = validateSessionId(input.sessionId);
    if (!this.settings.enabled) throw new BrowserError("BROWSER_DISABLED", "The built-in browser is disabled");
    if (!this.settings.automation.enabled) {
      throw new BrowserError("CAPABILITY_DISABLED", "Agent browser tools are disabled");
    }
    if (input.source === "channel" && !this.settings.automation.allowChannelSessions) {
      throw new BrowserError("CAPABILITY_DISABLED", "Browser access for channel sessions is disabled");
    }
    if (input.permission === "advanced") {
      if (!this.isHighRiskPermissionEnabled()) {
        throw new BrowserError("ADVANCED_CONFIRMATION_REQUIRED", "Advanced browser capabilities are disabled");
      }
    }
    const requestedTtl = input.expiresInMs ?? this.grantTtlMs;
    const ttl = Math.max(1_000, Math.min(requestedTtl, this.grantTtlMs));
    this.grants.set(sessionId, { ...input, sessionId, expiresAt: this.now() + ttl });
    this.bumpRevision();
    return input.permission === "none" ? undefined : this.issueLease(sessionId);
  }

  revokeSession(sessionId: string): BrowserCapabilitySnapshot {
    const normalized = validateSessionId(sessionId);
    this.grants.delete(normalized);
    for (const [id, lease] of this.leases) {
      if (lease.sessionId === normalized) this.leases.delete(id);
    }
    this.bumpRevision();
    return this.getSnapshot();
  }

  revokeAll(): BrowserCapabilitySnapshot {
    this.grants.clear();
    this.bumpRevision();
    return this.getSnapshot();
  }

  issueLease(sessionId: string): BrowserCapabilityLease {
    this.pruneExpired();
    const normalized = validateSessionId(sessionId);
    const grant = this.grants.get(normalized);
    if (!grant || grant.permission === "none") {
      throw new BrowserError("CAPABILITY_DISABLED", "This session has no Browser permission");
    }
    if (grant.permission === "advanced" && !this.isHighRiskPermissionEnabled()) {
      throw new BrowserError("CAPABILITY_DISABLED", "Advanced Browser permission is no longer enabled");
    }
    const lease: BrowserCapabilityLease = {
      id: this.createId(),
      sessionId: normalized,
      permission: grant.permission,
      policyRevision: this.revision,
      expiresAt: Math.min(grant.expiresAt, this.now() + this.leaseTtlMs),
    };
    this.leases.set(lease.id, lease);
    return structuredClone(lease);
  }

  getLeaseForSession(sessionId: string): BrowserCapabilityLease | undefined {
    this.pruneExpired();
    const normalized = validateSessionId(sessionId);
    const lease = [...this.leases.values()]
      .filter((candidate) => candidate.sessionId === normalized && candidate.policyRevision === this.revision)
      .sort((left, right) => right.expiresAt - left.expiresAt)[0];
    return lease ? structuredClone(lease) : undefined;
  }

  assertRequest(context: BrowserHostRequestContext, required: BrowserPermissionLevel): BrowserCapabilityLease {
    this.pruneExpired();
    if (!this.settings.enabled) throw new BrowserError("BROWSER_DISABLED", "The built-in browser is disabled");
    if (!this.settings.automation.enabled) {
      throw new BrowserError("CAPABILITY_DISABLED", "Agent browser tools are disabled");
    }
    if (!context.requestId || context.requestId.length > 256 || /[\0\r\n]/.test(context.requestId)) {
      throw new BrowserError("INVALID_BROWSER_REQUEST", "Browser requestId is invalid");
    }
    if (context.policyRevision !== this.revision) {
      throw new BrowserError("POLICY_REVISION_MISMATCH", "Browser policy changed; refresh capabilities", {
        retryable: true,
        details: { expectedRevision: this.revision },
      });
    }
    const lease = this.leases.get(context.capabilityLeaseId);
    if (!lease || lease.expiresAt <= this.now()) {
      throw new BrowserError("CAPABILITY_LEASE_EXPIRED", "Browser capability lease expired", { retryable: true });
    }
    if (lease.policyRevision !== this.revision || lease.sessionId !== context.sessionId) {
      throw new BrowserError("CAPABILITY_LEASE_EXPIRED", "Browser capability lease is no longer valid", {
        retryable: true,
      });
    }
    if (PERMISSION_RANK[lease.permission] < PERMISSION_RANK[required]) {
      throw new BrowserError("CAPABILITY_DISABLED", `Browser ${required} permission is required`);
    }
    if (required === "advanced" && !this.isHighRiskPermissionEnabled()) {
      throw new BrowserError("ADVANCED_CONFIRMATION_REQUIRED", "Advanced browser capabilities are disabled");
    }
    return structuredClone(lease);
  }

  getSnapshot(): BrowserCapabilitySnapshot {
    this.pruneExpired();
    const sessionPermissions: Record<string, BrowserPermissionLevel> = {};
    for (const [sessionId, grant] of this.grants) sessionPermissions[sessionId] = grant.permission;
    return {
      revision: this.revision,
      browserEnabled: this.settings.enabled,
      automationEnabled: this.settings.automation.enabled,
      advancedEnabled: this.isHighRiskPermissionEnabled(),
      sessionPermissions,
      generatedAt: this.now(),
    };
  }

  private bumpRevision(): void {
    this.revision++;
    this.leases.clear();
    const snapshot = this.getSnapshot();
    for (const listener of this.listeners) listener(snapshot);
  }

  private pruneExpired(): void {
    const now = this.now();
    for (const [sessionId, grant] of this.grants) {
      if (grant.expiresAt <= now) this.grants.delete(sessionId);
    }
    for (const [id, lease] of this.leases) {
      if (lease.expiresAt <= now) this.leases.delete(id);
    }
  }

  private downgradeAdvancedGrants(): void {
    for (const [sessionId, grant] of this.grants) {
      if (grant.permission === "advanced") this.grants.set(sessionId, { ...grant, permission: "interact" });
    }
  }
}

export function createDisabledAdvancedRuntimePolicy(): BrowserAdvancedRuntimePolicy {
  return {
    enabled: false,
    removeSiteSecurityHeaders: false,
    disableWebSecurity: false,
    allowInsecureContent: false,
    certificateBypassDomains: [],
    unrestrictedRawCdp: false,
  };
}

function validateSessionId(sessionId: string): string {
  const normalized = sessionId.trim();
  if (!normalized || normalized.length > 256 || /[\0\r\n]/.test(normalized)) {
    throw new BrowserError("INVALID_BROWSER_REQUEST", "Browser sessionId is invalid");
  }
  return normalized;
}

import { StringDecoder } from "node:string_decoder";
import type {
  ManagedProcessLogGap,
  ManagedProcessLogRecord,
  ManagedProcessLogStream,
  ManagedProcessOutputSummary,
} from "../../contract/processes.ts";
import { MANAGED_PROCESS_LIMITS, sanitizeManagedProcessText } from "../../shared/managed-process-policy.ts";

export interface ManagedOutputReadResult {
  fromCursor: string;
  nextCursor: string;
  earliestCursor: string;
  records: ManagedProcessLogRecord[];
  truncated: boolean;
  gap?: ManagedProcessLogGap;
}

function recordBytes(record: Pick<ManagedProcessLogRecord, "text">): number {
  return Buffer.byteLength(record.text, "utf8");
}

export function managedProcessCursor(runId: string, seq: number): string {
  return `${runId}:${Math.max(0, Math.floor(seq))}`;
}

export function parseManagedProcessCursor(cursor: string, expectedRunId: string): number | null {
  const separator = cursor.lastIndexOf(":");
  if (separator <= 0 || cursor.slice(0, separator) !== expectedRunId) return null;
  const value = Number(cursor.slice(separator + 1));
  return Number.isSafeInteger(value) && value >= 0 ? value : null;
}

export class ManagedProcessOutputBuffer {
  readonly runId: string;
  private readonly maxBytes: number;
  private readonly maxRecords: number;
  private records: ManagedProcessLogRecord[] = [];
  private head = 0;
  private nextSeq = 1;
  private bytes = 0;
  private droppedBytes = 0;
  private droppedRecords = 0;

  constructor(
    runId: string,
    maxBytes = MANAGED_PROCESS_LIMITS.processBytes,
    maxRecords = MANAGED_PROCESS_LIMITS.processRecords,
  ) {
    this.runId = runId;
    this.maxBytes = maxBytes;
    this.maxRecords = maxRecords;
  }

  append(stream: ManagedProcessLogStream, text: string, timestamp = Date.now()): ManagedProcessLogRecord | null {
    const sanitized = sanitizeManagedProcessText(text);
    if (!sanitized) return null;
    const record: ManagedProcessLogRecord = {
      seq: this.nextSeq++,
      timestamp,
      stream,
      text: sanitized,
      runId: this.runId,
    };
    this.records.push(record);
    this.bytes += recordBytes(record);
    this.trimToLimits();
    return record;
  }

  dropOldest(): boolean {
    const record = this.records[this.head];
    if (!record) return false;
    this.head += 1;
    const bytes = recordBytes(record);
    this.bytes -= bytes;
    this.droppedBytes += bytes;
    this.droppedRecords += 1;
    if (this.head >= 4_096 && this.head * 2 >= this.records.length) {
      this.records = this.records.slice(this.head);
      this.head = 0;
    }
    return true;
  }

  read(
    cursor: string | undefined,
    maxBytes: number,
    streams?: readonly ManagedProcessLogStream[],
  ): ManagedOutputReadResult {
    const earliestSeq = this.records[this.head]?.seq ?? this.nextSeq;
    const latestSeq = this.nextSeq - 1;
    const parsed = cursor ? parseManagedProcessCursor(cursor, this.runId) : earliestSeq - 1;
    const requestedSeq = parsed ?? earliestSeq - 1;
    const fromCursor = managedProcessCursor(this.runId, requestedSeq);
    const gap = requestedSeq < earliestSeq - 1 ? this.gap() : undefined;
    const startingSeq = Math.max(requestedSeq + 1, earliestSeq);
    const streamSet = streams?.length ? new Set(streams) : null;
    const selected: ManagedProcessLogRecord[] = [];
    let selectedBytes = 0;
    let nextSeq = Math.max(requestedSeq, earliestSeq - 1);
    let truncated = false;

    for (let index = this.head; index < this.records.length; index += 1) {
      const record = this.records[index];
      if (record.seq < startingSeq) continue;
      if (streamSet && !streamSet.has(record.stream)) {
        nextSeq = record.seq;
        continue;
      }
      const bytes = recordBytes(record);
      if (selected.length > 0 && selectedBytes + bytes > maxBytes) {
        truncated = true;
        break;
      }
      selected.push({ ...record });
      selectedBytes += bytes;
      nextSeq = record.seq;
      if (selectedBytes >= maxBytes) {
        truncated = record.seq < latestSeq;
        break;
      }
    }

    if (!truncated && nextSeq < latestSeq && selected.length === 0) nextSeq = latestSeq;
    return {
      fromCursor,
      nextCursor: managedProcessCursor(this.runId, nextSeq),
      earliestCursor: managedProcessCursor(this.runId, earliestSeq - 1),
      records: selected,
      truncated,
      ...(gap ? { gap } : {}),
    };
  }

  summary(): ManagedProcessOutputSummary {
    const earliestSeq = this.records[this.head]?.seq ?? this.nextSeq;
    return {
      earliestCursor: managedProcessCursor(this.runId, earliestSeq - 1),
      latestCursor: managedProcessCursor(this.runId, this.nextSeq - 1),
      retainedBytes: this.bytes,
      droppedBytes: this.droppedBytes,
      droppedRecords: this.droppedRecords,
    };
  }

  allRecords(): ManagedProcessLogRecord[] {
    return this.records.slice(this.head).map((record) => ({ ...record }));
  }

  retainedBytes(): number {
    return this.bytes;
  }

  private trimToLimits(): void {
    while (this.records.length - this.head > this.maxRecords || this.bytes > this.maxBytes) {
      if (!this.dropOldest()) break;
    }
  }

  private gap(): ManagedProcessLogGap | undefined {
    if (this.droppedRecords <= 0 && this.droppedBytes <= 0) return undefined;
    return { droppedBytes: this.droppedBytes, droppedRecords: this.droppedRecords };
  }
}

type DecoderState = {
  decoder: StringDecoder;
  line: string;
  retainedBytes: number;
  omittedBytes: number;
  carriageReturn: boolean;
};

export class ManagedProcessOutputDecoder {
  private readonly onLine: (stream: "stdout" | "stderr", line: string) => void;
  private readonly onEncodingWarning?: () => void;
  private decodedCharacters = 0;
  private replacementCharacters = 0;
  private encodingWarningSent = false;
  private readonly states: Record<"stdout" | "stderr", DecoderState> = {
    stdout: this.createState(),
    stderr: this.createState(),
  };

  constructor(onLine: (stream: "stdout" | "stderr", line: string) => void, onEncodingWarning?: () => void) {
    this.onLine = onLine;
    this.onEncodingWarning = onEncodingWarning;
  }

  write(stream: "stdout" | "stderr", chunk: Buffer | string): void {
    const state = this.states[stream];
    const decoded = typeof chunk === "string" ? chunk : state.decoder.write(chunk);
    if (!this.encodingWarningSent) {
      if (!/[\u{10000}-\u{10FFFF}\uFFFD]/u.test(decoded)) {
        this.decodedCharacters += decoded.length;
      } else {
        for (const character of decoded) {
          this.decodedCharacters += 1;
          if (character === "\uFFFD") this.replacementCharacters += 1;
        }
      }
      if (
        this.decodedCharacters >= 32 &&
        this.replacementCharacters >= 4 &&
        this.replacementCharacters * 10 >= this.decodedCharacters
      ) {
        this.encodingWarningSent = true;
        this.onEncodingWarning?.();
      }
    }
    this.consume(stream, state, decoded);
  }

  end(stream: "stdout" | "stderr"): void {
    const state = this.states[stream];
    this.consume(stream, state, state.decoder.end());
    if (state.carriageReturn || state.line || state.omittedBytes) this.flush(stream, state);
  }

  private createState(): DecoderState {
    return { decoder: new StringDecoder("utf8"), line: "", retainedBytes: 0, omittedBytes: 0, carriageReturn: false };
  }

  private consume(stream: "stdout" | "stderr", state: DecoderState, value: string): void {
    let offset = 0;
    while (offset < value.length) {
      if (state.carriageReturn) {
        state.carriageReturn = false;
        if (value[offset] === "\n") {
          this.flush(stream, state);
          offset += 1;
          continue;
        }
        state.line = "";
        state.retainedBytes = 0;
        state.omittedBytes = 0;
      }

      const carriageReturn = value.indexOf("\r", offset);
      const lineFeed = value.indexOf("\n", offset);
      const boundary =
        carriageReturn < 0 ? lineFeed : lineFeed < 0 ? carriageReturn : Math.min(carriageReturn, lineFeed);
      const end = boundary < 0 ? value.length : boundary;
      this.appendSegment(state, value.slice(offset, end));
      if (boundary < 0) break;
      offset = boundary + 1;
      if (value[boundary] === "\r") {
        state.carriageReturn = true;
        continue;
      }
      this.flush(stream, state);
    }
  }

  private appendSegment(state: DecoderState, segment: string): void {
    if (!segment) return;
    const segmentBytes = Buffer.byteLength(segment, "utf8");
    const remaining = MANAGED_PROCESS_LIMITS.lineBytes - state.retainedBytes;
    if (segmentBytes <= remaining) {
      state.line += segment;
      state.retainedBytes += segmentBytes;
      return;
    }
    if (remaining <= 0) {
      state.omittedBytes += segmentBytes;
      return;
    }
    let retained = "";
    let retainedBytes = 0;
    let omittedBytes = 0;
    for (const character of segment) {
      const bytes = Buffer.byteLength(character, "utf8");
      if (retainedBytes + bytes <= remaining) {
        retained += character;
        retainedBytes += bytes;
      } else {
        omittedBytes += bytes;
      }
    }
    state.line += retained;
    state.retainedBytes += retainedBytes;
    state.omittedBytes += omittedBytes;
  }

  private flush(stream: "stdout" | "stderr", state: DecoderState): void {
    const suffix = state.omittedBytes > 0 ? ` <line truncated: ${state.omittedBytes} bytes>` : "";
    this.onLine(stream, `${state.line}${suffix}`);
    state.line = "";
    state.retainedBytes = 0;
    state.omittedBytes = 0;
    state.carriageReturn = false;
  }
}
import path from "node:path";
import { realpath } from "node:fs/promises";
import { createHash } from "node:crypto";
import type { ManagedLoopbackEndpoint, ManagedProcessLogStream } from "../contract/processes.ts";

export const MANAGED_PROCESS_LIMITS = {
  commandBytes: 32 * 1024,
  labelCodePoints: 80,
  lineBytes: 16 * 1024,
  processBytes: 2 * 1024 * 1024,
  processRecords: 10_000,
  globalBytes: 16 * 1024 * 1024,
  agentReadDefaultBytes: 32 * 1024,
  agentReadMaxBytes: 128 * 1024,
  rendererReadDefaultBytes: 64 * 1024,
  rendererReadMaxBytes: 256 * 1024,
  stdinBytes: 64 * 1024,
  sessionActive: 4,
  globalActive: 8,
  exitedRecords: 64,
  exitedRetentionMs: 15 * 60_000,
  waitDefaultMs: 10_000,
  waitMaxMs: 30_000,
  startWaitDefaultMs: 1_000,
  startWaitMaxMs: 10_000,
  endpointCount: 8,
} as const;

const BLOCKED_COMMANDS: Array<{ pattern: RegExp; reason: string }> = [
  { pattern: /(?:^|[;&|()\s])nohup(?:\s|$)/i, reason: "nohup detaches the process from the manager" },
  { pattern: /(?:^|[;&|()\s])disown(?:\s|$)/i, reason: "disown detaches the process from the manager" },
  { pattern: /(?:^|[;&|()\s])setsid(?:\s|$)/i, reason: "setsid creates an unmanaged process group" },
  { pattern: /(?:^|[;&|()\s])daemonize(?:\s|$)/i, reason: "daemonize escapes managed lifecycle" },
  { pattern: /(?:^|[;&|()\s])systemd-run(?:\s|$)/i, reason: "systemd-run creates an external service" },
  { pattern: /(?:^|[;&|()\s])launchctl\s+submit(?:\s|$)/i, reason: "launchctl creates an external service" },
  {
    pattern: /(?:^|[;&|()\s])open\s+-a\s+(?:Terminal|iTerm)(?:\s|$)/i,
    reason: "external terminal processes are unmanaged",
  },
  { pattern: /(?:^|[;&|()\s])start\s+\/b(?:\s|$)/i, reason: "start /b is not supported by managed processes" },
  { pattern: /\bStart-Process\b/i, reason: "PowerShell Start-Process is not supported by managed processes" },
  { pattern: /(?:^|[;&|()\s])runas(?:\.exe)?(?:\s|$)/i, reason: "elevated processes cannot be managed" },
  {
    pattern: /(?:^|[;&|()\s])schtasks(?:\.exe)?(?:\s|$)/i,
    reason: "Task Scheduler processes are outside managed containment",
  },
  {
    pattern: /(?:^|[;&|()\s])sc(?:\.exe)?\s+(?:create|start)(?:\s|$)/i,
    reason: "Windows services are outside managed containment",
  },
  {
    pattern: /(?:^|[;&|()\s])wmic(?:\.exe)?\s+process\s+call\s+create(?:\s|$)/i,
    reason: "WMI-created processes are outside managed containment",
  },
  {
    pattern: /(?:^|[;&|()\s])wt(?:\.exe)?(?:\s|$)/i,
    reason: "external terminal processes are unmanaged",
  },
  {
    pattern: /(?:^|[;&|()\s])cmd(?:\.exe)?\s+(?:\/d\s+)?(?:\/s\s+)?(?:\/c\s+)?start(?:\s|$)/i,
    reason: "external terminal processes are unmanaged",
  },
  { pattern: /(?:^|[^&])&\s*(?:$|[\r\n])/, reason: "background shell control is not allowed" },
  { pattern: /(?:^|[^&>])&(?![&>])(?=\s|$)/, reason: "background shell control is not allowed" },
  { pattern: /&!\s*(?:$|[\r\n])/, reason: "background shell control is not allowed" },
];

const LAN_BIND_PATTERNS = [
  /(?:--host(?:=|\s+)|\bHOST=)(?:0\.0\.0\.0|::)(?::\d+)?(?:\s|$)/i,
  /(?:--listen(?:=|\s+)|\bBIND=)(?:0\.0\.0\.0|::)(?::\d+)?(?:\s|$)/i,
];

const ANSI_OSC = /\u001b\](?:[^\u0007\u001b]|\u001b(?!\\))*(?:\u0007|\u001b\\)/g;
const ANSI_CSI = /\u001b\[[0-?]*[ -/]*[@-~]/g;
const ANSI_SINGLE = /\u001b[@-_]/g;
const URL_CREDENTIALS = /([a-z][a-z0-9+.-]*:\/\/)[^\s/@:]+:[^\s/@]+@/gi;
const AUTHORIZATION_HEADER = /\b(authorization)(\s*[:=]\s*)(?:(?:bearer|basic)\s+)?[^\s,;]+/gi;
const SECRET_CLI_ARGUMENT =
  /(--(?:api[_-]?key|access[_-]?token|refresh[_-]?token|token|password|secret|npm[_-]?token|node[_-]?auth[_-]?token)(?:=|\s+))([^\s]+)/gi;
const COMMON_SECRET_TOKEN =
  /\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|sk-[A-Za-z0-9_-]{20,}|npm_[A-Za-z0-9]{20,}|xox[baprs]-[A-Za-z0-9-]{20,}|eyJ[A-Za-z0-9_-]{12,}\.[A-Za-z0-9_-]{12,}\.[A-Za-z0-9_-]{8,})\b/g;
const SECRET_ASSIGNMENT =
  /\b(authorization|cookie|set-cookie|api[_-]?key|access[_-]?token|refresh[_-]?token|token|password|secret|npm_token|node_auth_token)(\s*[:=]\s*)([^\s,;]+)/gi;
const PI_NONCE = /\b(PI_DESKTOP_[A-Z0-9_]*(?:NONCE|TOKEN|SECRET))=([^\s]+)/g;

export class ManagedProcessPolicyError extends Error {
  readonly code: "PROCESS_CWD_DENIED" | "PROCESS_COMMAND_BLOCKED" | "PROCESS_CONFIRMATION_REQUIRED";

  constructor(
    code: "PROCESS_CWD_DENIED" | "PROCESS_COMMAND_BLOCKED" | "PROCESS_CONFIRMATION_REQUIRED",
    message: string,
  ) {
    super(message);
    this.name = "ManagedProcessPolicyError";
    this.code = code;
  }
}

function codePointSlice(value: string, length: number): string {
  return [...value].slice(0, length).join("");
}

export function normalizeManagedProcessLabel(label: unknown, command: string): string {
  const candidate = typeof label === "string" ? label : command.trim().split(/\s+/u).slice(0, 3).join(" ");
  const clean = candidate
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return codePointSlice(clean || "Managed process", MANAGED_PROCESS_LIMITS.labelCodePoints);
}

export function validateManagedProcessCommand(command: unknown, allowLanBind = false): string {
  if (typeof command !== "string" || !command.trim()) {
    throw new ManagedProcessPolicyError("PROCESS_COMMAND_BLOCKED", "command is required");
  }
  if (Buffer.byteLength(command, "utf8") > MANAGED_PROCESS_LIMITS.commandBytes) {
    throw new ManagedProcessPolicyError("PROCESS_COMMAND_BLOCKED", "command exceeds the 32 KiB limit");
  }
  if (command.includes("\0") || command.includes("\uFFFD")) {
    throw new ManagedProcessPolicyError("PROCESS_COMMAND_BLOCKED", "command contains invalid characters");
  }
  for (const blocked of BLOCKED_COMMANDS) {
    if (blocked.pattern.test(command)) {
      throw new ManagedProcessPolicyError("PROCESS_COMMAND_BLOCKED", blocked.reason);
    }
  }
  if (!allowLanBind && LAN_BIND_PATTERNS.some((pattern) => pattern.test(command))) {
    throw new ManagedProcessPolicyError(
      "PROCESS_CONFIRMATION_REQUIRED",
      "command appears to bind to all network interfaces; use 127.0.0.1 or start it from the UI after review",
    );
  }
  return command;
}

function canonicalComparison(value: string): string {
  const normalized = path.normalize(value);
  return process.platform === "win32" ? normalized.toLocaleLowerCase("en-US") : normalized;
}

export async function resolveManagedProcessCwd(ownerCwd: string, requestedCwd?: string): Promise<string> {
  if (!path.isAbsolute(ownerCwd)) {
    throw new ManagedProcessPolicyError("PROCESS_CWD_DENIED", "owner workspace is not an absolute path");
  }
  const ownerReal = await realpath(ownerCwd).catch(() => null);
  const targetInput = requestedCwd
    ? path.isAbsolute(requestedCwd)
      ? requestedCwd
      : path.resolve(ownerCwd, requestedCwd)
    : ownerCwd;
  const targetReal = await realpath(targetInput).catch(() => null);
  if (!ownerReal || !targetReal) {
    throw new ManagedProcessPolicyError("PROCESS_CWD_DENIED", "managed process cwd does not exist");
  }
  const relative = path.relative(canonicalComparison(ownerReal), canonicalComparison(targetReal));
  if (relative === "" || (!relative.startsWith(`..${path.sep}`) && relative !== ".." && !path.isAbsolute(relative))) {
    return targetReal;
  }
  throw new ManagedProcessPolicyError(
    "PROCESS_CWD_DENIED",
    "managed process cwd must remain inside the owner workspace",
  );
}

export function sanitizeManagedProcessText(value: string): string {
  let sanitized = value.replace(ANSI_OSC, "").replace(ANSI_CSI, "").replace(ANSI_SINGLE, "");
  // URL_CREDENTIALS begins with an unconstrained scheme scan. Avoid its
  // quadratic no-match path for the common case of long, URL-free build logs.
  if (sanitized.includes("://")) sanitized = sanitized.replace(URL_CREDENTIALS, "$1[redacted]@");
  return sanitized
    .replace(AUTHORIZATION_HEADER, "$1$2[redacted]")
    .replace(SECRET_CLI_ARGUMENT, "$1[redacted]")
    .replace(SECRET_ASSIGNMENT, (_match, key: string, separator: string) => `${key}${separator}[redacted]`)
    .replace(PI_NONCE, "$1=[redacted]")
    .replace(COMMON_SECRET_TOKEN, "[redacted]")
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/g, "");
}

export function managedProcessCommandDisplay(command: string): string {
  const value = sanitizeManagedProcessText(command).replace(/\s+/g, " ").trim();
  return codePointSlice(value, 240) + ([...value].length > 240 ? "…" : "");
}

export function managedProcessCommandHash(command: string): string {
  return createHash("sha256").update(command, "utf8").digest("hex").slice(0, 16);
}

export function relativeManagedProcessCwd(ownerCwd: string, cwd: string): string {
  const relative = path.relative(ownerCwd, cwd).replace(/\\/g, "/");
  return relative && !relative.startsWith("../") ? relative : ".";
}

function safeLoopbackUrl(raw: string): string | null {
  try {
    const url = new URL(raw.replace(/[),.;]+$/, ""));
    if (url.protocol !== "http:" && url.protocol !== "https:") return null;
    const hostname = url.hostname.toLowerCase();
    if (hostname !== "localhost" && hostname !== "127.0.0.1" && hostname !== "[::1]" && hostname !== "::1") {
      return null;
    }
    url.username = "";
    url.password = "";
    url.hash = "";
    for (const key of [...url.searchParams.keys()]) {
      if (/token|key|secret|password|auth|signature/i.test(key)) url.searchParams.set(key, "[redacted]");
    }
    return url.toString();
  } catch {
    return null;
  }
}

export function extractManagedLoopbackEndpoints(
  text: string,
  stream: Exclude<ManagedProcessLogStream, "system">,
  runId: string,
  now = Date.now(),
): ManagedLoopbackEndpoint[] {
  const matches = text.match(/https?:\/\/(?:localhost|127\.0\.0\.1|\[::1\])(?::\d{1,5})?(?:\/[^\s<>"']*)?/gi) ?? [];
  const unique = new Set<string>();
  const endpoints: ManagedLoopbackEndpoint[] = [];
  for (const match of matches) {
    const url = safeLoopbackUrl(match);
    if (!url || unique.has(url)) continue;
    unique.add(url);
    endpoints.push({
      id: createHash("sha256").update(`${runId}\0${url}`, "utf8").digest("hex").slice(0, 16),
      url,
      source: stream,
      firstSeenAt: now,
      lastSeenAt: now,
      runId,
    });
    if (endpoints.length >= MANAGED_PROCESS_LIMITS.endpointCount) break;
  }
  return endpoints;
}

export function managedProcessNetworkWarnings(command: string, outputText = ""): string[] {
  const combined = `${command}\n${outputText}`;
  const warnings: string[] = [];
  if (
    LAN_BIND_PATTERNS.some((pattern) => pattern.test(combined)) ||
    /https?:\/\/(?:0\.0\.0\.0|\[?::\]?)(?::\d+)?/i.test(outputText)
  ) {
    warnings.push("Process may be reachable from the local network");
  }
  return warnings;
}

export function normalizeManagedReadBytes(value: unknown, renderer: boolean): number {
  const fallback = renderer
    ? MANAGED_PROCESS_LIMITS.rendererReadDefaultBytes
    : MANAGED_PROCESS_LIMITS.agentReadDefaultBytes;
  const maximum = renderer ? MANAGED_PROCESS_LIMITS.rendererReadMaxBytes : MANAGED_PROCESS_LIMITS.agentReadMaxBytes;
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value <= 0) return fallback;
  return Math.min(value, maximum);
}

export function normalizeManagedWaitMs(value: unknown, forStart = false): number {
  const fallback = forStart ? MANAGED_PROCESS_LIMITS.startWaitDefaultMs : MANAGED_PROCESS_LIMITS.waitDefaultMs;
  const maximum = forStart ? MANAGED_PROCESS_LIMITS.startWaitMaxMs : MANAGED_PROCESS_LIMITS.waitMaxMs;
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) return fallback;
  return Math.min(Math.floor(value), maximum);
}

#![cfg_attr(not(windows), allow(dead_code))]

mod error;
mod json;
mod protocol;
mod state;
#[cfg(windows)]
mod win32;

#[cfg(windows)]
mod windows_main {
    use super::error::{HelperError, Result};
    use super::json::{self, Value};
    use super::protocol::{
        Frame, FrameReader, FrameWriter, HELPER_ACTIVE_ZERO, HELPER_ERROR, HELPER_EXIT,
        HELPER_HELLO, HELPER_JOURNAL_DIRECTORY_SECURED, HELPER_OUTPUT_DROPPED, HELPER_PONG,
        HELPER_PREPARED, HELPER_REAP_OUTCOME, HELPER_STARTED, HELPER_STDERR, HELPER_STDIN_CLOSED,
        HELPER_STDOUT, HELPER_STOPPING, HOST_BOOTSTRAP, HOST_CLOSE_STDIN, HOST_COMMIT, HOST_PING,
        HOST_REAP, HOST_SECURE_JOURNAL_DIRECTORY, HOST_SHUTDOWN, HOST_STDIN, HOST_STOP,
        PROTOCOL_VERSION,
    };
    use super::state::{
        Bootstrap, Commit, ReapRequest, SecureJournalDirectoryRequest, Stdin, Stop, StopMode,
    };
    use super::win32::{self, Job, Target};
    use std::io::{Read, Write};
    use std::sync::Arc;
    use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
    use std::sync::mpsc::{
        self, Receiver, RecvTimeoutError, SyncSender, TryRecvError, TrySendError,
    };
    use std::time::{Duration, Instant};

    const BUILD_ID: &str = match option_env!("PIMPD_BUILD_ID") {
        Some(value) => value,
        None => "pimpd-0.1.0-p1-dev",
    };
    const PROVENANCE: &str = match option_env!("PIMPD_PROVENANCE") {
        Some(value) => value,
        None => "source-dev",
    };

    #[derive(Debug)]
    struct Packet {
        kind: u16,
        payload: Vec<u8>,
    }

    #[derive(Clone)]
    struct EventSink {
        control: SyncSender<Packet>,
        output: SyncSender<Packet>,
        dropped_bytes: Arc<AtomicU64>,
        dropped_chunks: Arc<AtomicU64>,
    }

    impl EventSink {
        fn start() -> Self {
            let (control_tx, control_rx) = mpsc::sync_channel::<Packet>(64);
            let (output_tx, output_rx) = mpsc::sync_channel::<Packet>(256);
            std::thread::spawn(move || writer_loop(control_rx, output_rx));
            Self {
                control: control_tx,
                output: output_tx,
                dropped_bytes: Arc::new(AtomicU64::new(0)),
                dropped_chunks: Arc::new(AtomicU64::new(0)),
            }
        }

        fn send_control(&self, kind: u16, payload: Vec<u8>) -> Result<()> {
            self.flush_dropped()?;
            self.control
                .send(Packet { kind, payload })
                .map_err(|_| HelperError::protocol("HELPER_PARENT_UNAVAILABLE"))
        }

        fn send_json(&self, kind: u16, payload: String) -> Result<()> {
            self.send_control(kind, payload.into_bytes())
        }

        fn send_output(&self, kind: u16, payload: Vec<u8>) {
            let bytes = payload.len() as u64;
            match self.output.try_send(Packet { kind, payload }) {
                Ok(()) => {}
                Err(TrySendError::Full(_) | TrySendError::Disconnected(_)) => {
                    self.dropped_bytes.fetch_add(bytes, Ordering::Relaxed);
                    self.dropped_chunks.fetch_add(1, Ordering::Relaxed);
                }
            }
        }

        fn flush_dropped(&self) -> Result<()> {
            let bytes = self.dropped_bytes.swap(0, Ordering::AcqRel);
            let chunks = self.dropped_chunks.swap(0, Ordering::AcqRel);
            if bytes == 0 && chunks == 0 {
                return Ok(());
            }
            let payload = format!(r#"{{"bytes":{bytes},"chunks":{chunks}}}"#).into_bytes();
            self.control
                .send(Packet {
                    kind: HELPER_OUTPUT_DROPPED,
                    payload,
                })
                .map_err(|_| HelperError::protocol("HELPER_PARENT_UNAVAILABLE"))
        }
    }

    fn writer_loop(control: Receiver<Packet>, output: Receiver<Packet>) {
        let mut writer = FrameWriter::new(std::io::stdout());
        loop {
            match control.try_recv() {
                Ok(packet) => {
                    if writer.write(packet.kind, &packet.payload).is_err() {
                        break;
                    }
                    continue;
                }
                Err(TryRecvError::Disconnected) => break,
                Err(TryRecvError::Empty) => {}
            }
            match output.recv_timeout(Duration::from_millis(20)) {
                Ok(packet) => {
                    if writer.write(packet.kind, &packet.payload).is_err() {
                        break;
                    }
                }
                Err(RecvTimeoutError::Timeout) => {}
                Err(RecvTimeoutError::Disconnected) => {
                    match control.recv_timeout(Duration::from_millis(20)) {
                        Ok(packet) => {
                            if writer.write(packet.kind, &packet.payload).is_err() {
                                break;
                            }
                        }
                        Err(_) => break,
                    }
                }
            }
        }
    }

    enum ControlMessage {
        Frame(Frame),
        Eof,
        Error(HelperError),
    }

    fn start_control_reader() -> Receiver<ControlMessage> {
        let (sender, receiver) = mpsc::channel();
        std::thread::spawn(move || {
            let mut reader = FrameReader::new(std::io::stdin());
            loop {
                match reader.read() {
                    Ok(Some(frame)) => {
                        if sender.send(ControlMessage::Frame(frame)).is_err() {
                            break;
                        }
                    }
                    Ok(None) => {
                        let _ = sender.send(ControlMessage::Eof);
                        break;
                    }
                    Err(error) => {
                        let _ = sender.send(ControlMessage::Error(error));
                        break;
                    }
                }
            }
        });
        receiver
    }

    fn hello() -> String {
        format!(
            r#"{{"protocolVersion":{},"buildId":{},"arch":"x64","provenance":{},"capabilities":["job","two-phase","owner-watchdog","reaper"]}}"#,
            PROTOCOL_VERSION,
            super::protocol::json_escape(BUILD_ID),
            super::protocol::json_escape(PROVENANCE),
        )
    }

    fn error_json(error: &HelperError) -> String {
        format!(
            r#"{{"subcode":{},"win32Code":{}}}"#,
            super::protocol::json_escape(error.subcode),
            error.win32_code
        )
    }

    fn control_with_timeout(
        receiver: &Receiver<ControlMessage>,
        timeout: Duration,
    ) -> Result<Frame> {
        match receiver.recv_timeout(timeout) {
            Ok(ControlMessage::Frame(frame)) => Ok(frame),
            Ok(ControlMessage::Eof) => Err(HelperError::protocol("HELPER_PARENT_UNAVAILABLE")),
            Ok(ControlMessage::Error(error)) => Err(error),
            Err(_) => Err(HelperError::protocol("HELPER_PARENT_UNAVAILABLE")),
        }
    }

    fn drain(mut input: std::fs::File, kind: u16, sink: EventSink) {
        let mut buffer = vec![0_u8; 16 * 1024];
        loop {
            match input.read(&mut buffer) {
                Ok(0) => break,
                Ok(read) => sink.send_output(kind, buffer[..read].to_vec()),
                Err(error) if error.kind() == std::io::ErrorKind::Interrupted => {}
                Err(_) => break,
            }
        }
    }

    fn parse_ping(bytes: &[u8]) -> Result<u64> {
        let mut object = json::parse(bytes)?.object()?;
        let value = match object.remove("sequence") {
            Some(Value::Integer(value)) if value >= 0 => value as u64,
            _ => return Err(HelperError::protocol("HELPER_INVALID_FRAME")),
        };
        if !object.is_empty() {
            return Err(HelperError::protocol("HELPER_INVALID_FRAME"));
        }
        Ok(value)
    }

    fn stop_job(
        job: &Job,
        process_group_id: u32,
        mode: StopMode,
        sink: &EventSink,
    ) -> Result<&'static str> {
        if mode == StopMode::Graceful {
            sink.send_json(HELPER_STOPPING, r#"{"phase":"interrupt"}"#.into())?;
            let _ = win32::send_ctrl_c();
            if job.wait_empty(Duration::from_secs(2))? {
                return Ok("CTRL_C_EVENT");
            }
            sink.send_json(HELPER_STOPPING, r#"{"phase":"terminate"}"#.into())?;
            let _ = win32::send_ctrl_break(process_group_id);
            if job.wait_empty(Duration::from_secs(3))? {
                return Ok("CTRL_BREAK_EVENT");
            }
        }
        sink.send_json(HELPER_STOPPING, r#"{"phase":"force"}"#.into())?;
        job.terminate()?;
        if !job.wait_empty(Duration::from_millis(1_500))? {
            return Err(HelperError::protocol("JOB_TERMINATE_FAILED"));
        }
        Ok("JOB_TERMINATE")
    }

    fn owner_mode(sink: &EventSink) -> Result<()> {
        let receiver = start_control_reader();
        let frame = control_with_timeout(&receiver, Duration::from_secs(10))?;
        if frame.kind != HOST_BOOTSTRAP {
            return Err(HelperError::protocol("HELPER_INVALID_FRAME"));
        }
        let bootstrap = Bootstrap::parse(&frame.payload)?;
        let owners = win32::open_owner_handles(&bootstrap)?;
        let job = Arc::new(Job::create(&bootstrap.job_name)?);
        let mut target = Target::prepare(&bootstrap, &job)?;
        let helper_fingerprint = win32::current_process_fingerprint(BUILD_ID)?;
        sink.send_json(
            HELPER_PREPARED,
            format!(
                r#"{{"helperPid":{},"helperStartFingerprint":{},"jobName":{},"helperBuildId":{},"nonce":{},"hostInstanceId":{}}}"#,
                std::process::id(),
                super::protocol::json_escape(&helper_fingerprint),
                super::protocol::json_escape(&bootstrap.job_name),
                super::protocol::json_escape(BUILD_ID),
                super::protocol::json_escape(&bootstrap.nonce),
                super::protocol::json_escape(&bootstrap.host_instance_id),
            ),
        )?;
        let commit_frame = control_with_timeout(&receiver, Duration::from_secs(5))?;
        if commit_frame.kind != HOST_COMMIT {
            return Err(HelperError::protocol("HELPER_INVALID_FRAME"));
        }
        let commit = Commit::parse(&commit_frame.payload)?;
        if commit.nonce != bootstrap.nonce {
            return Err(HelperError::protocol("HELPER_INVALID_FRAME"));
        }
        target.resume()?;
        let pipes = target.take_pipes()?;
        let mut target_stdin = Some(pipes.stdin);
        let stdout_sink = sink.clone();
        std::thread::spawn(move || drain(pipes.stdout, HELPER_STDOUT, stdout_sink));
        let stderr_sink = sink.clone();
        std::thread::spawn(move || drain(pipes.stderr, HELPER_STDERR, stderr_sink));
        let owner_lost = Arc::new(AtomicBool::new(false));
        let watchdog_lost = Arc::clone(&owner_lost);
        let watchdog_job = Arc::clone(&job);
        std::thread::spawn(move || {
            if win32::wait_for_owner_loss(owners).is_ok() {
                watchdog_lost.store(true, Ordering::Release);
                let _ = watchdog_job.terminate();
            }
        });
        sink.send_json(
            HELPER_STARTED,
            format!(
                r#"{{"hostInstanceId":{},"journalRevision":{}}}"#,
                super::protocol::json_escape(&bootstrap.host_instance_id),
                commit.journal_revision,
            ),
        )?;

        let mut stopped: Option<(String, &'static str)> = None;
        let mut root_exit_at: Option<Instant> = None;
        let mut root_code: Option<u32> = None;
        loop {
            match receiver.recv_timeout(Duration::from_millis(50)) {
                Ok(ControlMessage::Frame(frame)) => match frame.kind {
                    HOST_STDIN => {
                        let input = Stdin::parse(&frame.payload)?;
                        if let Some(stdin) = target_stdin.as_mut() {
                            let written = stdin.write_all(input.text.as_bytes()).and_then(|()| {
                                if input.append_newline {
                                    stdin.write_all(b"\n")
                                } else {
                                    Ok(())
                                }
                            });
                            if written.is_err() {
                                target_stdin = None;
                                sink.send_json(HELPER_STDIN_CLOSED, "{}".into())?;
                            }
                        } else {
                            sink.send_json(HELPER_STDIN_CLOSED, "{}".into())?;
                        }
                    }
                    HOST_CLOSE_STDIN => {
                        target_stdin = None;
                        sink.send_json(HELPER_STDIN_CLOSED, "{}".into())?;
                    }
                    HOST_STOP | HOST_SHUTDOWN => {
                        let stop = if frame.kind == HOST_STOP {
                            Stop::parse(&frame.payload)?
                        } else {
                            Stop {
                                mode: StopMode::Graceful,
                                source: "host".into(),
                            }
                        };
                        let signal = stop_job(&job, target.process_id, stop.mode, sink)?;
                        stopped = Some((stop.source, signal));
                    }
                    HOST_PING => {
                        let sequence = parse_ping(&frame.payload)?;
                        sink.send_json(HELPER_PONG, format!(r#"{{"sequence":{sequence}}}"#))?;
                    }
                    _ => return Err(HelperError::protocol("HELPER_INVALID_FRAME")),
                },
                Ok(ControlMessage::Eof) => {
                    owner_lost.store(true, Ordering::Release);
                    job.terminate()?;
                }
                Ok(ControlMessage::Error(error)) => return Err(error),
                Err(RecvTimeoutError::Disconnected) => {
                    owner_lost.store(true, Ordering::Release);
                    job.terminate()?;
                }
                Err(RecvTimeoutError::Timeout) => {}
            }

            if root_code.is_none() {
                root_code = target.exit_code()?;
                if root_code.is_some() {
                    root_exit_at = Some(Instant::now());
                }
            }
            let active = job.active_processes()?;
            if active == 0 {
                sink.send_json(HELPER_ACTIVE_ZERO, "{}".into())?;
                let exit = if let Some((source, signal)) = stopped {
                    format!(
                        r#"{{"code":null,"signal":{},"reason":"stopped","source":{}}}"#,
                        super::protocol::json_escape(signal),
                        super::protocol::json_escape(&source)
                    )
                } else if owner_lost.load(Ordering::Acquire) {
                    r#"{"code":null,"reason":"host-failure"}"#.into()
                } else {
                    format!(
                        r#"{{"code":{},"reason":"exit"}}"#,
                        root_code.map_or_else(|| "null".into(), |value| value.to_string())
                    )
                };
                sink.send_json(HELPER_EXIT, exit)?;
                std::thread::sleep(Duration::from_millis(100));
                return Ok(());
            }
            if stopped.is_some() {
                return Err(HelperError::protocol("JOB_TERMINATE_FAILED"));
            }
            if root_exit_at.is_some_and(|started| started.elapsed() >= Duration::from_secs(1)) {
                let _ = stop_job(&job, target.process_id, StopMode::Force, sink)?;
                stopped = Some(("host".into(), "JOB_TERMINATE"));
            }
        }
    }

    fn reaper_mode(sink: &EventSink) -> Result<()> {
        let receiver = start_control_reader();
        let frame = control_with_timeout(&receiver, Duration::from_secs(5))?;
        if frame.kind == HOST_SECURE_JOURNAL_DIRECTORY {
            let request = SecureJournalDirectoryRequest::parse(&frame.payload)?;
            win32::secure_journal_directory(&request.path)?;
            sink.send_json(
                HELPER_JOURNAL_DIRECTORY_SECURED,
                r#"{"secured":true}"#.into(),
            )?;
            std::thread::sleep(Duration::from_millis(100));
            return Ok(());
        }
        if frame.kind != HOST_REAP {
            return Err(HelperError::protocol("HELPER_INVALID_FRAME"));
        }
        let request = ReapRequest::parse(&frame.payload)?;
        let Some(job) = Job::open_for_reap(&request.job_name)? else {
            sink.send_json(HELPER_REAP_OUTCOME, r#"{"outcome":"already-empty"}"#.into())?;
            std::thread::sleep(Duration::from_millis(100));
            return Ok(());
        };
        let Some(owner) = win32::open_reap_owner(
            request.helper_pid,
            &request.helper_start_fingerprint,
            &request.helper_build_id,
        )?
        else {
            sink.send_json(
                HELPER_REAP_OUTCOME,
                r#"{"outcome":"identity-uncertain"}"#.into(),
            )?;
            std::thread::sleep(Duration::from_millis(100));
            return Ok(());
        };
        if job.active_processes()? > 0 {
            job.terminate()?;
        }
        if !job.wait_empty(Duration::from_millis(1_500))? {
            return Err(HelperError::protocol("JOB_TERMINATE_FAILED"));
        }
        win32::terminate_reap_owner(&owner)?;
        sink.send_json(HELPER_REAP_OUTCOME, r#"{"outcome":"removed"}"#.into())?;
        std::thread::sleep(Duration::from_millis(100));
        Ok(())
    }

    fn version_mode() {
        println!(
            r#"{{"protocolVersion":{},"buildId":{},"arch":"x64","provenance":{}}}"#,
            PROTOCOL_VERSION,
            super::protocol::json_escape(BUILD_ID),
            super::protocol::json_escape(PROVENANCE),
        );
    }

    fn self_test_mode() -> Result<()> {
        let job_name = format!(
            r"Local\PiDesktop.Managed.SelfTest.{:08x}",
            std::process::id()
        );
        let job = Job::create(&job_name)?;
        if job.active_processes()? != 0 {
            return Err(HelperError::protocol("JOB_QUERY_FAILED"));
        }
        println!(
            r#"{{"ok":true,"protocolVersion":{},"buildId":{},"arch":"x64","checks":["job-dacl","kill-on-close","completion-port","accounting"]}}"#,
            PROTOCOL_VERSION,
            super::protocol::json_escape(BUILD_ID),
        );
        Ok(())
    }

    pub fn run() -> i32 {
        let mode = std::env::args().nth(1);
        let _executable_lock = if matches!(
            mode.as_deref(),
            Some("--owner-stdio-v1") | Some("--reap-stdio-v1")
        ) {
            match win32::lock_current_executable() {
                Ok(lock) => Some(lock),
                Err(_) => return 2,
            }
        } else {
            None
        };
        if mode.as_deref() == Some("--version-json-v1") {
            version_mode();
            return 0;
        }
        if mode.as_deref() == Some("--self-test-json-v1") {
            return match self_test_mode() {
                Ok(()) => 0,
                Err(_) => 2,
            };
        }
        let sink = EventSink::start();
        if sink.send_json(HELPER_HELLO, hello()).is_err() {
            return 2;
        }
        let result = match mode.as_deref() {
            Some("--owner-stdio-v1") => owner_mode(&sink),
            Some("--reap-stdio-v1") => reaper_mode(&sink),
            _ => Err(HelperError::protocol("HELPER_PROTOCOL_MISMATCH")),
        };
        match result {
            Ok(()) => 0,
            Err(error) => {
                let _ = sink.send_json(HELPER_ERROR, error_json(&error));
                // Give the dedicated writer a bounded chance to emit the fixed
                // diagnostic before process teardown closes the Job handle.
                std::thread::sleep(Duration::from_millis(200));
                2
            }
        }
    }
}

