import { spawn, type ChildProcess } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import { EventEmitter } from "node:events";
import { readFile, realpath } from "node:fs/promises";
import path from "node:path";
import type {
  ManagedProcessExit,
  ManagedProcessStopMode,
  ManagedProcessStopSource,
  WindowsManagedProcessReaperRecord,
} from "../../contract/processes.ts";
import type { WindowsManagedProcessHelperDescriptor } from "../../shared/windows-managed-process-helper.ts";
import { evaluateHeartbeatTick } from "../../shared/heartbeat-liveness.ts";
import type {
  ManagedProcessBackend,
  ManagedProcessBackendEvent,
  PreparedContainment,
  PreparedManagedProcessLaunch,
  StartedContainment,
} from "./backend.ts";
import {
  WINDOWS_HELPER_BOOTSTRAP_MAX_BYTES,
  WINDOWS_HELPER_KIND,
  WindowsHelperFrameDecoder,
  encodeWindowsHelperJson,
  parseWindowsHelperJson,
  type WindowsHelperFrame,
} from "./helper-codec.ts";

const HELLO_TIMEOUT_MS = 2_000;
const PREPARE_TIMEOUT_MS = 5_000;
const START_TIMEOUT_MS = 2_000;
const PING_INTERVAL_MS = 15_000;
const PING_TIMEOUT_MS = 10_000;
const OUTPUT_FORWARD_RATE_BYTES_PER_SECOND = 128 * 1024;
const OUTPUT_FORWARD_BURST_BYTES = 64 * 1024;
const SAFE_HELPER_SUBCODES = new Set([
  "HELPER_PROTOCOL_MISMATCH",
  "HELPER_INVALID_FRAME",
  "HELPER_BOOTSTRAP_TOO_LARGE",
  "HELPER_PARENT_UNAVAILABLE",
  "HELPER_PARENT_TIME_MISMATCH",
  "HELPER_PARENT_IMAGE_MISMATCH",
  "JOB_CREATE_FAILED",
  "JOB_LIMIT_FAILED",
  "JOB_COMPLETION_PORT_FAILED",
  "CONSOLE_SETUP_FAILED",
  "PIPE_SETUP_FAILED",
  "TARGET_CREATE_FAILED",
  "TARGET_ASSIGN_FAILED",
  "TARGET_RESUME_FAILED",
  "JOB_QUERY_FAILED",
  "JOB_TERMINATE_FAILED",
  "TARGET_COMMAND_LINE_TOO_LONG",
  "TARGET_ENVIRONMENT_TOO_LARGE",
  "HELPER_INTEGRITY_FAILED",
]);

type Deferred<T> = {
  promise: Promise<T>;
  resolve(value: T): void;
  reject(error: Error): void;
};

function deferred<T>(): Deferred<T> {
  let resolve!: (value: T) => void;
  let reject!: (error: Error) => void;
  const promise = new Promise<T>((ok, fail) => {
    resolve = ok;
    reject = fail;
  });
  return { promise, resolve, reject };
}

function withTimeout<T>(promise: Promise<T>, timeoutMs: number, message: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(message)), timeoutMs);
    timer.unref();
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

function exactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return Object.keys(value).sort().join("\0") === [...keys].sort().join("\0");
}

function normalizeEnvironment(
  environment: NodeJS.ProcessEnv,
  processId: string,
  runId: string,
): Record<string, string> {
  const folded = new Map<string, { key: string; value: string }>();
  for (const [key, value] of Object.entries(environment)) {
    if (typeof value !== "string" || key.toLocaleLowerCase("en-US") === "electron_run_as_node") continue;
    const comparable = key.toLocaleLowerCase("en-US");
    if (folded.has(comparable)) throw new Error("Windows environment contains duplicate case-insensitive keys");
    folded.set(comparable, { key, value });
  }
  for (const [key, value] of [
    ["PI_DESKTOP_MANAGED_PROCESS", "1"],
    ["PI_DESKTOP_MANAGED_PROCESS_ID", processId],
    ["PI_DESKTOP_MANAGED_RUN_ID", runId],
  ]) {
    folded.set(key.toLocaleLowerCase("en-US"), { key, value });
  }
  if (folded.size > 4_096) throw new Error("Windows environment exceeds the 4096 entry limit");
  const entries = [...folded.values()].sort((left, right) =>
    left.key.localeCompare(right.key, "en-US", { sensitivity: "base" }),
  );
  let blockUnits = 1;
  const result: Record<string, string> = {};
  for (const { key, value } of entries) {
    if (!key || /[=\0]/u.test(key) || value.includes("\0")) throw new Error("Windows environment is invalid");
    const entryUnits = key.length + value.length + 2;
    if (entryUnits > 32_767) throw new Error("Windows environment entry is too large");
    blockUnits += entryUnits;
    result[key] = value;
  }
  if (blockUnits * 2 > 256 * 1024) throw new Error("Windows environment block exceeds 256 KiB");
  if (Buffer.byteLength(JSON.stringify(result), "utf8") > 256 * 1024)
    throw new Error("Windows environment JSON exceeds 256 KiB");
  return result;
}

function safeHelperEnvironment(): NodeJS.ProcessEnv {
  const environment: NodeJS.ProcessEnv = {};
  for (const key of ["SystemRoot", "WINDIR"]) {
    const value = process.env[key];
    if (value) environment[key] = value;
  }
  return environment;
}

export class WindowsJobProcessBackend implements ManagedProcessBackend {
  private readonly descriptor: WindowsManagedProcessHelperDescriptor;
  private readonly spawnProcess: typeof spawn;
  private process?: ChildProcess;
  private readonly events = new EventEmitter();
  private readonly decoder = new WindowsHelperFrameDecoder();
  private readonly waiters = new Map<number, Array<Deferred<WindowsHelperFrame>>>();
  private readonly pendingFrames = new Map<number, WindowsHelperFrame[]>();
  private readonly exited = deferred<void>();
  private sequence = 1;
  private exitReported = false;
  private pingTimer?: ReturnType<typeof setInterval>;
  private pingSequence = 0;
  private lastPongAt = Date.now();
  private lastPingTickAt = Date.now();
  private failed = false;
  private discardOutput = false;
  private discardedOutputBytes = 0;
  private discardedOutputChunks = 0;
  private readonly outputBudgets = {
    stdout: { available: OUTPUT_FORWARD_BURST_BYTES, updatedAt: Date.now() },
    stderr: { available: OUTPUT_FORWARD_BURST_BYTES, updatedAt: Date.now() },
  };

  constructor(descriptor: WindowsManagedProcessHelperDescriptor, spawnProcess: typeof spawn = spawn) {
    this.descriptor = descriptor;
    this.spawnProcess = spawnProcess;
  }

  get child(): ChildProcess | undefined {
    return this.process;
  }

  onEvent(listener: (event: ManagedProcessBackendEvent) => void): () => void {
    this.events.on("event", listener);
    return () => this.events.off("event", listener);
  }

  async prepare(input: PreparedManagedProcessLaunch, signal?: AbortSignal): Promise<PreparedContainment> {
    if (this.process) throw new Error("Windows helper backend was already prepared");
    await this.verifyDescriptor();
    if (signal?.aborted) throw new Error("Windows helper start was cancelled");
    const owner = input.owner;
    if (!owner) throw new Error("Windows helper owner identity is unavailable");
    const environment = normalizeEnvironment(input.context.shellEnv, input.processId, input.runId);
    const nonce = randomBytes(32).toString("hex");
    const jobName = `Local\\PiDesktop.Managed.${nonce}`;
    const bootstrap = {
      version: 1,
      processIdHash: createHash("sha256").update(input.processId, "utf8").digest("hex"),
      runIdHash: createHash("sha256").update(input.runId, "utf8").digest("hex"),
      jobName,
      nonce,
      cwd: input.cwd,
      shellExecutable: input.shell.executable,
      argvPrefix: [...input.shell.argvPrefix],
      command: input.command,
      environment,
      mainPid: owner.mainPid,
      mainStartTimeMs: Number(owner.mainStartFingerprint),
      mainImagePath: owner.mainImagePath,
      hostPid: owner.hostPid,
      hostStartTimeMs: Number(owner.hostStartFingerprint),
      hostImagePath: owner.hostImagePath,
      hostInstanceId: owner.hostInstanceId,
    };
    const serialized = JSON.stringify(bootstrap);
    if (Buffer.byteLength(serialized, "utf8") > WINDOWS_HELPER_BOOTSTRAP_MAX_BYTES)
      throw new Error("Windows helper bootstrap exceeds 512 KiB");
    const metadata = JSON.stringify({ ...bootstrap, command: "", environment: {} });
    if (Buffer.byteLength(metadata, "utf8") > 32 * 1024) throw new Error("Windows helper metadata exceeds 32 KiB");

    const helper = this.spawnProcess(this.descriptor.path, ["--owner-stdio-v1"], {
      cwd: path.dirname(this.descriptor.path),
      env: safeHelperEnvironment(),
      shell: false,
      windowsHide: true,
      detached: false,
      stdio: ["pipe", "pipe", "pipe"],
    });
    this.process = helper;
    helper.stdin?.on("error", (error) => {
      const pipeError = error instanceof Error ? error : new Error("Windows helper control pipe failed");
      if (this.exitReported || helper.exitCode !== null || helper.signalCode !== null) {
        this.rejectWaiters(pipeError);
        return;
      }
      this.fail(pipeError);
    });
    let safeStderrBytes = 0;
    helper.stderr?.on("data", (chunk: Buffer) => {
      safeStderrBytes += chunk.length;
      if (safeStderrBytes > 4_096) this.fail(new Error("Windows helper stderr exceeded its diagnostic limit"));
    });
    helper.stdout?.on("data", (chunk: Buffer) => {
      helper.stdout?.pause();
      setTimeout(() => {
        this.handleBytes(chunk);
        helper.stdout?.resume();
      }, 0);
    });
    helper.stdout?.once("end", () => {
      try {
        this.decoder.finish();
      } catch (error) {
        this.fail(error instanceof Error ? error : new Error("Windows helper output was truncated"));
      }
    });
    helper.once("error", () => this.fail(new Error("Windows helper failed to start")));
    helper.once("close", (code) => {
      this.stopPing();
      this.flushDiscardedOutput();
      if (!this.exitReported) {
        this.exitReported = true;
        this.events.emit("event", {
          type: "exit",
          exit: { code: null, reason: "host-failure" },
        } satisfies ManagedProcessBackendEvent);
      }
      this.rejectWaiters(new Error(`Windows helper exited with code ${code ?? "unknown"}`));
      this.exited.resolve();
    });
    const abort = () => void this.dispose();
    signal?.addEventListener("abort", abort, { once: true });
    try {
      const helloFrame = await withTimeout(
        this.waitForFrame(WINDOWS_HELPER_KIND.hello),
        HELLO_TIMEOUT_MS,
        "Windows helper hello timed out",
      );
      this.validateHello(parseWindowsHelperJson(helloFrame));
      this.send(WINDOWS_HELPER_KIND.bootstrap, serialized);
      const preparedFrame = await withTimeout(
        this.waitForFrame(WINDOWS_HELPER_KIND.prepared),
        PREPARE_TIMEOUT_MS,
        "Windows helper prepare timed out",
      );
      const prepared = this.validatePrepared(
        parseWindowsHelperJson(preparedFrame),
        owner.hostInstanceId,
        jobName,
        nonce,
      );
      const reaper: WindowsManagedProcessReaperRecord = {
        version: 2,
        platform: "win32",
        processId: input.processId,
        runId: input.runId,
        hostInstanceId: owner.hostInstanceId,
        helperPid: prepared.helperPid,
        helperStartFingerprint: prepared.helperStartFingerprint,
        jobName,
        helperBuildId: this.descriptor.buildId,
        nonce,
        createdAt: Date.now(),
      };
      return { reaper, privateState: { nonce, hostInstanceId: owner.hostInstanceId } };
    } finally {
      signal?.removeEventListener("abort", abort);
    }
  }

  async commit(prepared: PreparedContainment, journalRevision: number): Promise<StartedContainment> {
    if (prepared.reaper.platform !== "win32" || !prepared.privateState || typeof prepared.privateState !== "object")
      throw new Error("Invalid Windows prepared containment");
    const state = prepared.privateState as { nonce?: unknown; hostInstanceId?: unknown };
    if (typeof state.nonce !== "string" || typeof state.hostInstanceId !== "string")
      throw new Error("Invalid Windows prepared state");
    this.send(WINDOWS_HELPER_KIND.commit, JSON.stringify({ nonce: state.nonce, journalRevision }));
    const startedFrame = await withTimeout(
      this.waitForFrame(WINDOWS_HELPER_KIND.started),
      START_TIMEOUT_MS,
      "Windows helper commit timed out",
    );
    const started = parseWindowsHelperJson(startedFrame);
    if (
      !exactKeys(started, ["hostInstanceId", "journalRevision"]) ||
      started.hostInstanceId !== state.hostInstanceId ||
      started.journalRevision !== journalRevision
    ) {
      throw new Error("Windows helper started identity mismatch");
    }
    this.startPing();
    return { started: true };
  }

  write(input: { text: string; appendNewline: boolean; close: boolean }): void {
    this.send(WINDOWS_HELPER_KIND.stdin, JSON.stringify({ text: input.text, appendNewline: input.appendNewline }));
    if (input.close) this.send(WINDOWS_HELPER_KIND.closeStdin, "{}");
  }

  async stop(mode: ManagedProcessStopMode, source: ManagedProcessStopSource): Promise<void> {
    if (!this.process || this.process.exitCode !== null) return;
    this.discardOutput = true;
    this.send(WINDOWS_HELPER_KIND.stop, JSON.stringify({ mode, source }));
  }

  waitForExit(): Promise<void> {
    return this.exited.promise;
  }

  async dispose(): Promise<void> {
    this.stopPing();
    const child = this.process;
    if (!child || child.exitCode !== null || child.signalCode !== null) return;
    try {
      this.send(WINDOWS_HELPER_KIND.shutdown, "{}");
    } catch {
      // The helper may already be exiting; killing the helper closes the Job.
    }
    await Promise.race([
      this.exited.promise,
      new Promise<void>((resolve) => {
        const timer = setTimeout(() => {
          try {
            child.kill();
          } catch {
            // Process already exited.
          }
          resolve();
        }, 1_500);
        timer.unref();
      }),
    ]);
  }

  private async verifyDescriptor(): Promise<void> {
    const canonical = await realpath(this.descriptor.path);
    if (canonical !== this.descriptor.path) throw new Error("Windows helper path is not canonical");
    const bytes = await readFile(canonical);
    const actual = createHash("sha256").update(bytes).digest("hex");
    if (actual !== this.descriptor.sha256) throw new Error("Windows helper integrity check failed");
  }

  private send(kind: number, payload: string): void {
    const stdin = this.process?.stdin;
    if (!stdin || stdin.destroyed || stdin.writableEnded) throw new Error("Windows helper control pipe is closed");
    const frame = encodeWindowsHelperJson(kind, this.sequence++, JSON.parse(payload));
    if (!stdin.write(frame)) {
      // Node continues draining the bounded write internally; callers remain
      // subject to the service's existing stdin rate limit.
    }
  }

  private waitForFrame(kind: number): Promise<WindowsHelperFrame> {
    const pending = this.pendingFrames.get(kind);
    if (pending?.length) {
      const frame = pending.shift()!;
      if (!pending.length) this.pendingFrames.delete(kind);
      return Promise.resolve(frame);
    }
    const waiter = deferred<WindowsHelperFrame>();
    const waiters = this.waiters.get(kind) ?? [];
    waiters.push(waiter);
    this.waiters.set(kind, waiters);
    return waiter.promise;
  }

  private handleBytes(chunk: Buffer): void {
    try {
      for (const frame of this.decoder.push(chunk)) this.handleFrame(frame);
    } catch (error) {
      this.fail(error instanceof Error ? error : new Error("Invalid Windows helper output"));
    }
  }

  private handleFrame(frame: WindowsHelperFrame): void {
    const waiting = this.waiters.get(frame.kind);
    if (waiting?.length) {
      waiting.shift()!.resolve(frame);
      if (!waiting.length) this.waiters.delete(frame.kind);
      return;
    }
    if (
      frame.kind === WINDOWS_HELPER_KIND.hello ||
      frame.kind === WINDOWS_HELPER_KIND.prepared ||
      frame.kind === WINDOWS_HELPER_KIND.started ||
      frame.kind === WINDOWS_HELPER_KIND.reapOutcome
    ) {
      const pending = this.pendingFrames.get(frame.kind) ?? [];
      if (pending.length >= 1) return this.fail(new Error("Duplicate Windows helper lifecycle event"));
      pending.push(frame);
      this.pendingFrames.set(frame.kind, pending);
      return;
    }
    if (frame.kind === WINDOWS_HELPER_KIND.stdout || frame.kind === WINDOWS_HELPER_KIND.stderr) {
      const stream = frame.kind === WINDOWS_HELPER_KIND.stdout ? "stdout" : "stderr";
      if (this.discardOutput || !this.consumeOutputBudget(stream, frame.payload.length)) {
        this.discardedOutputBytes += frame.payload.length;
        this.discardedOutputChunks += 1;
        return;
      }
      this.events.emit("event", {
        type: stream,
        bytes: frame.payload,
      } satisfies ManagedProcessBackendEvent);
      return;
    }
    const value = parseWindowsHelperJson(frame);
    if (frame.kind === WINDOWS_HELPER_KIND.outputDropped) {
      if (
        !exactKeys(value, ["bytes", "chunks"]) ||
        !Number.isSafeInteger(value.bytes) ||
        (value.bytes as number) < 0 ||
        !Number.isSafeInteger(value.chunks) ||
        (value.chunks as number) < 0
      ) {
        return this.fail(new Error("Invalid Windows helper output drop event"));
      }
      this.discardedOutputBytes += value.bytes as number;
      this.discardedOutputChunks += value.chunks as number;
      return;
    }
    this.flushDiscardedOutput();
    if (frame.kind === WINDOWS_HELPER_KIND.stdinClosed) {
      if (!exactKeys(value, [])) return this.fail(new Error("Invalid Windows helper stdin event"));
      this.events.emit("event", { type: "stdin-closed" } satisfies ManagedProcessBackendEvent);
      return;
    }
    if (frame.kind === WINDOWS_HELPER_KIND.stopping) {
      if (!exactKeys(value, ["phase"]) || !["interrupt", "terminate", "force"].includes(String(value.phase)))
        return this.fail(new Error("Invalid Windows helper stopping event"));
      this.events.emit("event", {
        type: "stopping",
        phase: value.phase as "interrupt" | "terminate" | "force",
      } satisfies ManagedProcessBackendEvent);
      return;
    }
    if (frame.kind === WINDOWS_HELPER_KIND.activeZero) {
      if (!exactKeys(value, [])) return this.fail(new Error("Invalid Windows helper active-zero event"));
      return;
    }
    if (frame.kind === WINDOWS_HELPER_KIND.exit) {
      const exit = this.validateExit(value);
      this.exitReported = true;
      this.stopPing();
      this.flushDiscardedOutput();
      this.events.emit("event", { type: "exit", exit } satisfies ManagedProcessBackendEvent);
      return;
    }
    if (frame.kind === WINDOWS_HELPER_KIND.error) {
      if (
        !exactKeys(value, ["subcode", "win32Code"]) ||
        typeof value.subcode !== "string" ||
        !SAFE_HELPER_SUBCODES.has(value.subcode) ||
        !Number.isSafeInteger(value.win32Code) ||
        (value.win32Code as number) < 0
      ) {
        return this.fail(new Error("Windows helper returned an unsafe error"));
      }
      this.events.emit("event", { type: "error", subcode: value.subcode } satisfies ManagedProcessBackendEvent);
      this.fail(new Error(`${value.subcode} (${value.win32Code})`));
      return;
    }
    if (frame.kind === WINDOWS_HELPER_KIND.pong) {
      if (!exactKeys(value, ["sequence"]) || value.sequence !== this.pingSequence)
        return this.fail(new Error("Windows helper pong mismatch"));
      this.lastPongAt = Date.now();
      return;
    }
    this.fail(new Error("Unexpected Windows helper event"));
  }

  private flushDiscardedOutput(): void {
    if (this.discardedOutputChunks <= 0) return;
    this.events.emit("event", {
      type: "output-dropped",
      bytes: this.discardedOutputBytes,
      chunks: this.discardedOutputChunks,
    } satisfies ManagedProcessBackendEvent);
    this.discardedOutputBytes = 0;
    this.discardedOutputChunks = 0;
  }

  private consumeOutputBudget(stream: "stdout" | "stderr", bytes: number): boolean {
    const budget = this.outputBudgets[stream];
    const now = Date.now();
    const elapsedMs = Math.max(0, now - budget.updatedAt);
    budget.available = Math.min(
      OUTPUT_FORWARD_BURST_BYTES,
      budget.available + (elapsedMs * OUTPUT_FORWARD_RATE_BYTES_PER_SECOND) / 1_000,
    );
    budget.updatedAt = now;
    if (bytes > budget.available) return false;
    budget.available -= bytes;
    return true;
  }

  private validateHello(value: Record<string, unknown>): void {
    if (
      !exactKeys(value, ["protocolVersion", "buildId", "arch", "provenance", "capabilities"]) ||
      value.protocolVersion !== 1 ||
      value.buildId !== this.descriptor.buildId ||
      value.arch !== "x64" ||
      value.provenance !== this.descriptor.provenance ||
      !Array.isArray(value.capabilities) ||
      value.capabilities.join("\0") !== "job\0two-phase\0owner-watchdog\0reaper"
    ) {
      throw new Error("Windows helper hello mismatch");
    }
  }

  private validatePrepared(
    value: Record<string, unknown>,
    hostInstanceId: string,
    jobName: string,
    nonce: string,
  ): { helperPid: number; helperStartFingerprint: string } {
    if (
      !exactKeys(value, [
        "helperPid",
        "helperStartFingerprint",
        "jobName",
        "helperBuildId",
        "nonce",
        "hostInstanceId",
      ]) ||
      !Number.isSafeInteger(value.helperPid) ||
      (value.helperPid as number) <= 1 ||
      typeof value.helperStartFingerprint !== "string" ||
      value.helperStartFingerprint.length > 512 ||
      value.jobName !== jobName ||
      value.helperBuildId !== this.descriptor.buildId ||
      value.nonce !== nonce ||
      value.hostInstanceId !== hostInstanceId
    ) {
      throw new Error("Windows helper prepared identity mismatch");
    }
    return { helperPid: value.helperPid as number, helperStartFingerprint: value.helperStartFingerprint };
  }

  private validateExit(value: Record<string, unknown>): Omit<ManagedProcessExit, "finishedAt"> {
    const allowed = new Set(["code", "signal", "reason", "source"]);
    if (Object.keys(value).some((key) => !allowed.has(key))) throw new Error("Invalid Windows helper exit event");
    const code = value.code;
    if (code !== null && (!Number.isSafeInteger(code) || (code as number) < 0 || (code as number) > 0xffff_ffff))
      throw new Error("Invalid Windows helper exit code");
    if (!["exit", "stopped", "host-failure"].includes(String(value.reason)))
      throw new Error("Invalid Windows helper exit reason");
    const exit: Omit<ManagedProcessExit, "finishedAt"> = {
      code: code as number | null,
      reason: value.reason as "exit" | "stopped" | "host-failure",
    };
    if (
      typeof value.signal === "string" &&
      ["CTRL_C_EVENT", "CTRL_BREAK_EVENT", "JOB_TERMINATE"].includes(value.signal)
    )
      exit.signal = value.signal;
    if (typeof value.source === "string" && ["agent", "user", "host", "main"].includes(value.source))
      exit.stoppedBy = value.source as ManagedProcessStopSource;
    return exit;
  }

  private startPing(): void {
    const startedAt = Date.now();
    this.lastPongAt = startedAt;
    this.lastPingTickAt = startedAt;
    this.pingTimer = setInterval(() => {
      const now = Date.now();
      const heartbeat = evaluateHeartbeatTick({
        now,
        lastTickAt: this.lastPingTickAt,
        lastAcknowledgedAt: this.lastPongAt,
        intervalMs: PING_INTERVAL_MS,
        timeoutMs: PING_TIMEOUT_MS,
      });
      this.lastPingTickAt = now;
      if (heartbeat.clockDiscontinuity) this.lastPongAt = now;
      if (heartbeat.timedOut) {
        this.fail(new Error("Windows helper heartbeat timed out"));
        return;
      }
      this.pingSequence += 1;
      try {
        this.send(WINDOWS_HELPER_KIND.ping, JSON.stringify({ sequence: this.pingSequence }));
      } catch (error) {
        this.fail(error instanceof Error ? error : new Error("Windows helper heartbeat failed"));
      }
    }, PING_INTERVAL_MS);
    this.pingTimer.unref();
  }

  private stopPing(): void {
    if (this.pingTimer) clearInterval(this.pingTimer);
    this.pingTimer = undefined;
  }

  private fail(error: Error): void {
    if (!this.failed) {
      this.failed = true;
      this.events.emit("event", {
        type: "error",
        subcode: "WINDOWS_HELPER_BACKEND_FAILED",
        message: error.message,
      } satisfies ManagedProcessBackendEvent);
    }
    this.rejectWaiters(error);
    const child = this.process;
    if (child && child.exitCode === null && child.signalCode === null) {
      try {
        child.kill();
      } catch {
        // Already exited.
      }
    }
  }

  private rejectWaiters(error: Error): void {
    for (const waiters of this.waiters.values()) for (const waiter of waiters) waiter.reject(error);
    this.waiters.clear();
  }
}

import { createHash } from "node:crypto";
import fs from "node:fs";
import { once } from "node:events";
import path from "node:path";
import { isCatalogArtifactUrlAllowed, type RuntimeCatalogVariant } from "../../shared/toolchains/catalog-schema.ts";
import { ToolchainError } from "../../shared/toolchains/errors.ts";
import type { ManagedComponentId } from "../../shared/toolchains/types.ts";

const DOWNLOAD_TIMEOUT_MS = 10 * 60_000;
export const MAX_RUNTIME_REDIRECTS = 5;
const REDIRECT_HOSTS = new Set([
  "github.com",
  "release-assets.githubusercontent.com",
  "objects.githubusercontent.com",
  "nodejs.org",
  "releases.astral.sh",
]);

export interface DownloadProgress {
  downloadedBytes: number;
  totalBytes: number;
}

export interface RuntimeDownloaderOptions {
  fetchImpl?: typeof fetch;
  timeoutMs?: number;
  signal?: AbortSignal;
  onProgress?: (progress: DownloadProgress) => void;
}

export function assertRuntimeRedirectUrl(value: string): URL {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new ToolchainError({ code: "TOOLCHAIN_DOWNLOAD_REJECTED", message: "Artifact redirect is invalid" });
  }
  if (
    url.protocol !== "https:" ||
    url.username ||
    url.password ||
    url.hash ||
    !REDIRECT_HOSTS.has(url.hostname.toLowerCase())
  ) {
    throw new ToolchainError({ code: "TOOLCHAIN_DOWNLOAD_REJECTED", message: "Artifact redirect was rejected" });
  }
  return url;
}

async function fetchArtifact(
  componentId: ManagedComponentId,
  initialUrl: string,
  fetchImpl: typeof fetch,
  signal: AbortSignal,
): Promise<Response> {
  if (!isCatalogArtifactUrlAllowed(componentId, initialUrl)) {
    throw new ToolchainError({
      code: "TOOLCHAIN_DOWNLOAD_REJECTED",
      message: "Artifact URL is outside the catalog allowlist",
    });
  }
  let current = new URL(initialUrl);
  for (let redirects = 0; redirects <= MAX_RUNTIME_REDIRECTS; redirects += 1) {
    let response: Response;
    try {
      response = await fetchImpl(current, {
        redirect: "manual",
        signal,
        headers: {
          Accept: "application/octet-stream",
          "Accept-Encoding": "identity",
          "User-Agent": "Pi-Agent-Desktop-Toolchain-Installer",
        },
      });
    } catch (error) {
      const code = (error as { code?: unknown }).code;
      throw new ToolchainError({
        code:
          code === "ENOTFOUND" || code === "ECONNREFUSED"
            ? "TOOLCHAIN_DOWNLOAD_OFFLINE"
            : "TOOLCHAIN_DOWNLOAD_REJECTED",
        message: "Could not download the managed runtime artifact",
        cause: error,
        causeCode: typeof code === "string" ? code : undefined,
      });
    }
    if (response.status >= 300 && response.status < 400) {
      const location = response.headers.get("location");
      if (!location || redirects === MAX_RUNTIME_REDIRECTS) {
        throw new ToolchainError({ code: "TOOLCHAIN_DOWNLOAD_REJECTED", message: "Artifact redirect limit exceeded" });
      }
      current = assertRuntimeRedirectUrl(new URL(location, current).href);
      continue;
    }
    if (!response.ok || !response.body) {
      throw new ToolchainError({
        code: response.status >= 500 ? "TOOLCHAIN_DOWNLOAD_OFFLINE" : "TOOLCHAIN_DOWNLOAD_REJECTED",
        message: `Managed runtime download failed with HTTP ${response.status}`,
      });
    }
    return response;
  }
  throw new ToolchainError({ code: "TOOLCHAIN_DOWNLOAD_REJECTED", message: "Artifact redirect limit exceeded" });
}

export async function hashFile(filePath: string): Promise<{ sha256: string; bytes: number }> {
  const hash = createHash("sha256");
  let bytes = 0;
  const stream = fs.createReadStream(filePath);
  for await (const chunk of stream) {
    const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    bytes += buffer.length;
    hash.update(buffer);
  }
  return { sha256: hash.digest("hex"), bytes };
}

export async function verifyDownloadedArtifact(filePath: string, variant: RuntimeCatalogVariant): Promise<boolean> {
  try {
    const result = await hashFile(filePath);
    return result.bytes === variant.downloadBytes && result.sha256 === variant.sha256;
  } catch {
    return false;
  }
}

export async function downloadRuntimeArtifact(
  componentId: ManagedComponentId,
  variant: RuntimeCatalogVariant,
  destination: string,
  options: RuntimeDownloaderOptions = {},
): Promise<void> {
  if (options.signal?.aborted) {
    throw new ToolchainError({ code: "TOOLCHAIN_CANCELLED", message: "Managed runtime download was cancelled" });
  }
  const existingArtifactIsValid = await verifyDownloadedArtifact(destination, variant);
  if (options.signal?.aborted) {
    throw new ToolchainError({ code: "TOOLCHAIN_CANCELLED", message: "Managed runtime download was cancelled" });
  }
  if (existingArtifactIsValid) {
    options.onProgress?.({ downloadedBytes: variant.downloadBytes, totalBytes: variant.downloadBytes });
    return;
  }
  fs.mkdirSync(path.dirname(destination), { recursive: true, mode: 0o700 });
  try {
    fs.unlinkSync(destination);
  } catch {
    // Missing or stale files are replaced below.
  }
  const controller = new AbortController();
  let externallyAborted = false;
  const abortFromCaller = (): void => {
    externallyAborted = true;
    controller.abort();
  };
  options.signal?.addEventListener("abort", abortFromCaller, { once: true });
  if (options.signal?.aborted) abortFromCaller();
  const timer = setTimeout(() => controller.abort(), options.timeoutMs ?? DOWNLOAD_TIMEOUT_MS);
  timer.unref();
  try {
    const response = await fetchArtifact(componentId, variant.url, options.fetchImpl ?? fetch, controller.signal);
    const headerLength = response.headers.get("content-length");
    if (headerLength && Number(headerLength) !== variant.downloadBytes) {
      throw new ToolchainError({
        code: "TOOLCHAIN_INTEGRITY_FAILED",
        message: "Artifact size does not match the catalog",
      });
    }
    const hash = createHash("sha256");
    const output = fs.createWriteStream(destination, { flags: "wx", mode: 0o600 });
    let downloadedBytes = 0;
    try {
      for await (const value of response.body as unknown as AsyncIterable<Uint8Array>) {
        const chunk = Buffer.from(value);
        downloadedBytes += chunk.length;
        if (downloadedBytes > variant.downloadBytes) {
          throw new ToolchainError({
            code: "TOOLCHAIN_INTEGRITY_FAILED",
            message: "Artifact exceeds its catalog size",
          });
        }
        hash.update(chunk);
        if (!output.write(chunk)) await once(output, "drain");
        options.onProgress?.({ downloadedBytes, totalBytes: variant.downloadBytes });
      }
      output.end();
      await once(output, "close");
    } catch (error) {
      output.destroy();
      throw error;
    }
    if (downloadedBytes !== variant.downloadBytes || hash.digest("hex") !== variant.sha256) {
      throw new ToolchainError({
        code: "TOOLCHAIN_INTEGRITY_FAILED",
        message: "Artifact checksum does not match the catalog",
      });
    }
  } catch (error) {
    try {
      fs.unlinkSync(destination);
    } catch {
      // Best-effort partial cleanup.
    }
    if (externallyAborted || options.signal?.aborted) {
      throw new ToolchainError({
        code: "TOOLCHAIN_CANCELLED",
        message: "Managed runtime download was cancelled",
        cause: error,
      });
    }
    if (error instanceof ToolchainError) throw error;
    throw new ToolchainError({
      code: "TOOLCHAIN_DOWNLOAD_REJECTED",
      message: "Managed runtime download failed",
      cause: error,
    });
  } finally {
    clearTimeout(timer);
    options.signal?.removeEventListener("abort", abortFromCaller);
  }
}
import fs, { type Dirent } from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import type {
  RuntimeCatalog,
  RuntimeCatalogComponent,
  RuntimeCatalogVariant,
} from "../../shared/toolchains/catalog-schema.ts";
import { ToolchainError } from "../../shared/toolchains/errors.ts";
import type { ManagedComponentId, PublicToolchainOperation, ToolCandidate } from "../../shared/toolchains/types.ts";
import { MANAGED_COMPONENT_IDS } from "../../shared/toolchains/types.ts";
import { findCatalogComponent, findCatalogVariant } from "./catalog.ts";
import { findComponentEntrypoints } from "./component-entrypoint.ts";
import { downloadRuntimeArtifact, verifyDownloadedArtifact } from "./downloader.ts";
import type { ExecutableSeed, DiscoveryFileSystem } from "./discovery-registry.ts";
import { nodeDiscoveryFileSystem } from "./discovery-registry.ts";
import { extractRuntimeArchive } from "./secure-extractor.ts";
import { runtimeDirectory, type ToolchainPaths } from "./paths.ts";
import { probeExecutableSeed, type CapabilityProbeOptions } from "./probes/capabilities.ts";
import { defaultProbeExecutor, type ProbeExecutor } from "./process-runner.ts";
import { extractPortableGitSfx } from "./portable-git-installer.ts";
import { writeRuntimeManifest } from "./runtime-manifest.ts";
import { ToolchainStateStore, type ToolchainPersistentState } from "./state-store.ts";

export type InstallerProgress = Pick<PublicToolchainOperation, "phase" | "downloadedBytes" | "totalBytes" | "error">;

type DownloadFunction = typeof downloadRuntimeArtifact;
type ExtractFunction = typeof extractRuntimeArchive;
type PortableGitExtractFunction = typeof extractPortableGitSfx;
type ProbeFunction = (seed: ExecutableSeed, options: CapabilityProbeOptions) => Promise<ToolCandidate[]>;

export interface ManagedComponentInstallerOptions {
  paths: ToolchainPaths;
  stateStore: ToolchainStateStore;
  catalog: RuntimeCatalog;
  platform?: NodeJS.Platform;
  arch?: string;
  env?: NodeJS.ProcessEnv;
  tempRoot?: string;
  fileSystem?: DiscoveryFileSystem;
  executor?: ProbeExecutor;
  download?: DownloadFunction;
  fetchImpl?: typeof fetch;
  extract?: ExtractFunction;
  extractPortableGit?: PortableGitExtractFunction;
  probe?: ProbeFunction;
  now?: () => Date;
}

function safeArtifactCacheName(
  component: RuntimeCatalogComponent,
  variant: RuntimeCatalogVariant,
  platform: NodeJS.Platform,
  arch: string,
): string {
  const extension = variant.installer === "portable-git-sfx" ? ".7z.exe" : ".artifact";
  return `${component.id}-${component.version}-${platform}-${arch}${extension}`;
}

function isProcessAlive(pid: number): boolean {
  if (!Number.isSafeInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === "EPERM";
  }
}

function acquireComponentLock(paths: ToolchainPaths, componentId: ManagedComponentId): () => void {
  fs.mkdirSync(paths.locks, { recursive: true, mode: 0o700 });
  const lockPath = path.join(paths.locks, `${componentId}.lock`);
  for (let attempt = 0; attempt < 2; attempt += 1) {
    try {
      const descriptor = fs.openSync(lockPath, "wx", 0o600);
      fs.writeFileSync(descriptor, JSON.stringify({ pid: process.pid, createdAt: new Date().toISOString() }));
      fs.closeSync(descriptor);
      return () => {
        try {
          fs.unlinkSync(lockPath);
        } catch {
          // The operation already released or the app is shutting down.
        }
      };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
      try {
        const value = JSON.parse(fs.readFileSync(lockPath, "utf8")) as { pid?: unknown };
        if (typeof value.pid === "number" && isProcessAlive(value.pid)) break;
        fs.unlinkSync(lockPath);
        continue;
      } catch {
        break;
      }
    }
  }
  throw new ToolchainError({
    code: "TOOLCHAIN_INSTALL_BUSY",
    message: `Another ${componentId} installation is already running`,
  });
}

function maxExtractedBytes(component: RuntimeCatalogComponent, downloadBytes: number, installedBytes?: number): number {
  if (installedBytes) return installedBytes;
  const multiplier = component.id === "cpython" ? 40 : 20;
  return Math.min(4 * 1024 * 1024 * 1024, Math.max(downloadBytes, downloadBytes * multiplier));
}

function keyFilesFromCandidates(runtimeRoot: string, candidates: readonly ToolCandidate[]): string[] {
  const files: string[] = [];
  for (const candidate of candidates) {
    for (const value of [candidate.executable, ...(candidate.argvPrefix ?? [])]) {
      if (!path.isAbsolute(value)) continue;
      const relative = path.relative(runtimeRoot, value);
      if (relative && !relative.startsWith("..") && !path.isAbsolute(relative) && fs.existsSync(value))
        files.push(value);
    }
  }
  return files;
}

function singleBinaryName(componentId: ManagedComponentId, platform: NodeJS.Platform): string {
  const suffix = platform === "win32" ? ".exe" : "";
  if (componentId === "jq" || componentId === "bun" || componentId === "ripgrep" || componentId === "fd") {
    return `${componentId === "ripgrep" ? "rg" : componentId}${suffix}`;
  }
  throw new ToolchainError({
    code: "TOOLCHAIN_UNSUPPORTED",
    message: `${componentId} is not supported by the single-binary installer`,
  });
}

export class ManagedComponentInstaller {
  private readonly paths: ToolchainPaths;
  private readonly stateStore: ToolchainStateStore;
  private readonly catalog: RuntimeCatalog;
  private readonly platform: NodeJS.Platform;
  private readonly arch: string;
  private readonly env: NodeJS.ProcessEnv;
  private readonly tempRoot?: string;
  private readonly fileSystem: DiscoveryFileSystem;
  private readonly executor: ProbeExecutor;
  private readonly download: DownloadFunction;
  private readonly extract: ExtractFunction;
  private readonly extractPortableGit: PortableGitExtractFunction;
  private readonly probe: ProbeFunction;
  private readonly now: () => Date;

  constructor(options: ManagedComponentInstallerOptions) {
    this.paths = options.paths;
    this.stateStore = options.stateStore;
    this.catalog = options.catalog;
    this.platform = options.platform ?? process.platform;
    this.arch = options.arch ?? process.arch;
    this.env = { ...(options.env ?? process.env) };
    this.tempRoot = options.tempRoot;
    this.fileSystem = options.fileSystem ?? nodeDiscoveryFileSystem;
    this.executor = options.executor ?? defaultProbeExecutor;
    this.download =
      options.download ??
      ((componentId, variant, destination, downloadOptions) =>
        downloadRuntimeArtifact(componentId, variant, destination, {
          ...downloadOptions,
          fetchImpl: options.fetchImpl,
        }));
    this.extract = options.extract ?? extractRuntimeArchive;
    this.extractPortableGit = options.extractPortableGit ?? extractPortableGitSfx;
    this.probe = options.probe ?? probeExecutableSeed;
    this.now = options.now ?? (() => new Date());
  }

  async install(
    componentId: ManagedComponentId,
    onProgress: (progress: InstallerProgress) => void = () => {},
    signal?: AbortSignal,
  ): Promise<ToolchainPersistentState> {
    throwIfCancelled(signal, componentId);
    const releaseLock = acquireComponentLock(this.paths, componentId);
    let stagingRoot: string | undefined;
    let partialPath: string | undefined;
    try {
      const component = findCatalogComponent(this.catalog, componentId);
      const variant = findCatalogVariant(component, this.platform, this.arch);
      fs.mkdirSync(this.paths.downloads, { recursive: true, mode: 0o700 });
      const archivePath = path.join(
        this.paths.downloads,
        safeArtifactCacheName(component, variant, this.platform, this.arch),
      );
      partialPath = `${archivePath}.partial`;
      onProgress({ phase: "downloading", downloadedBytes: 0, totalBytes: variant.downloadBytes });
      if (!(await verifyDownloadedArtifact(archivePath, variant))) {
        await this.download(componentId, variant, partialPath, {
          signal,
          onProgress: ({ downloadedBytes, totalBytes }) =>
            onProgress({ phase: "downloading", downloadedBytes, totalBytes }),
        });
        throwIfCancelled(signal, componentId);
        onProgress({ phase: "verifying", downloadedBytes: variant.downloadBytes, totalBytes: variant.downloadBytes });
        if (!(await verifyDownloadedArtifact(partialPath, variant))) {
          throw new ToolchainError({
            code: "TOOLCHAIN_INTEGRITY_FAILED",
            message: "Downloaded artifact failed verification",
          });
        }
        try {
          fs.unlinkSync(archivePath);
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
        }
        fs.renameSync(partialPath, archivePath);
      } else {
        onProgress({ phase: "verifying", downloadedBytes: variant.downloadBytes, totalBytes: variant.downloadBytes });
      }

      throwIfCancelled(signal, componentId);
      fs.mkdirSync(this.paths.staging, { recursive: true, mode: 0o700 });
      stagingRoot = fs.mkdtempSync(path.join(this.paths.staging, `${componentId}-`));
      onProgress({ phase: "extracting" });
      if (variant.installer === "safe-archive") {
        await this.extract(archivePath, stagingRoot, variant.archive, {
          maxExtractedBytes: maxExtractedBytes(component, variant.downloadBytes, variant.installedBytes),
        });
      } else if (variant.installer === "single-binary") {
        const executable = path.join(stagingRoot, singleBinaryName(componentId, this.platform));
        fs.copyFileSync(archivePath, executable, fs.constants.COPYFILE_EXCL);
      } else if (variant.installer === "portable-git-sfx") {
        await this.extractPortableGit(archivePath, stagingRoot, {
          platform: this.platform,
          env: this.env,
          executor: this.executor,
        });
      } else {
        throw new ToolchainError({
          code: "TOOLCHAIN_UNSUPPORTED",
          message: `The ${componentId} installer is unsupported`,
        });
      }
      throwIfCancelled(signal, componentId);
      const entrypoints = findComponentEntrypoints(componentId, stagingRoot);
      if (this.platform !== "win32") {
        for (const entrypoint of entrypoints) fs.chmodSync(entrypoint.executable, 0o755);
      }
      const seeds: ExecutableSeed[] = entrypoints.map((entrypoint, index) => ({
        capability: entrypoint.capability,
        provider: "managed",
        discovery: `managed-staging:${componentId}`,
        executable: entrypoint.executable,
        argvPrefix: [],
        binDir: path.dirname(entrypoint.executable),
        componentId,
        componentRoot: stagingRoot,
        rank: 5_000 + index,
      }));
      onProgress({ phase: "probing" });
      const candidates = (
        await Promise.all(
          seeds.map((seed) =>
            this.probe(seed, {
              platform: this.platform,
              arch: this.arch,
              env: this.env,
              tempRoot: this.tempRoot,
              fileSystem: this.fileSystem,
              executor: this.executor,
            }),
          ),
        )
      ).flat();
      throwIfCancelled(signal, componentId);
      const healthy = new Set(
        candidates.filter((candidate) => candidate.health === "healthy").map((candidate) => candidate.capability),
      );
      const missing = component.provides.filter((capability) => !healthy.has(capability));
      if (missing.length > 0) {
        const permissionDenied = candidates.some(
          (candidate) =>
            missing.includes(candidate.capability) && candidate.reasonCode === "TOOLCHAIN_PERMISSION_DENIED",
        );
        throw new ToolchainError({
          code: permissionDenied ? "TOOLCHAIN_PERMISSION_DENIED" : "TOOLCHAIN_BROKEN",
          message: `Managed ${componentId} failed capability probe: ${missing.join(", ")}`,
        });
      }
      const platformArch = `${this.platform}-${this.arch}`;
      await writeRuntimeManifest({
        runtimeRoot: stagingRoot,
        component,
        platformArch,
        catalogRevision: this.catalog.revision,
        artifactSha256: variant.sha256,
        entrypoints,
        keyFiles: keyFilesFromCandidates(stagingRoot, candidates),
        installedAt: this.now().toISOString(),
      });

      throwIfCancelled(signal, componentId);
      onProgress({ phase: "activating" });
      const finalRoot = runtimeDirectory(this.paths, componentId, component.version, this.platform, this.arch);
      fs.mkdirSync(path.dirname(finalRoot), { recursive: true, mode: 0o700 });
      const previousRoot = fs.existsSync(finalRoot) ? `${finalRoot}.previous-${randomUUID()}` : undefined;
      if (previousRoot) fs.renameSync(finalRoot, previousRoot);
      try {
        fs.renameSync(stagingRoot, finalRoot);
        stagingRoot = undefined;
        const state = this.stateStore.update((draft) => {
          const previous = draft.managed[componentId];
          draft.managed[componentId] = {
            activeVersion: component.version,
            platformArch,
            installedVersions: [...new Set([...(previous?.installedVersions ?? []), component.version])],
          };
        });
        if (previousRoot) fs.rmSync(previousRoot, { recursive: true, force: true });
        onProgress({ phase: "ready", downloadedBytes: variant.downloadBytes, totalBytes: variant.downloadBytes });
        return state;
      } catch (error) {
        try {
          if (fs.existsSync(finalRoot)) fs.rmSync(finalRoot, { recursive: true, force: true });
          if (previousRoot && fs.existsSync(previousRoot)) fs.renameSync(previousRoot, finalRoot);
        } catch {
          // Preserve the original error; diagnostics will report any rollback residue.
        }
        throw error;
      }
    } catch (error) {
      const normalized =
        error instanceof ToolchainError
          ? error
          : new ToolchainError({
              code:
                (error as NodeJS.ErrnoException | undefined)?.code === "EACCES" ||
                (error as NodeJS.ErrnoException | undefined)?.code === "EPERM"
                  ? "TOOLCHAIN_PERMISSION_DENIED"
                  : "TOOLCHAIN_INTERNAL",
              message: error instanceof Error ? error.message : `Managed ${componentId} installation failed`,
              cause: error,
            });
      onProgress(
        normalized.code === "TOOLCHAIN_CANCELLED"
          ? { phase: "cancelled" }
          : { phase: "error", error: { code: normalized.code, message: normalized.message } },
      );
      throw normalized;
    } finally {
      if (stagingRoot) {
        try {
          fs.rmSync(stagingRoot, { recursive: true, force: true });
        } catch {
          // Best-effort staging cleanup.
        }
      }
      if (partialPath) {
        try {
          fs.unlinkSync(partialPath);
        } catch {
          // Missing or already-promoted partial artifacts need no cleanup.
        }
      }
      releaseLock();
    }
  }

  /**
   * Converges residue from a process termination before any Host session can
   * use managed files. Future-schema state is deliberately left untouched.
   */
  recoverInterruptedOperations(): void {
    cleanupPartialDownloads(this.paths.downloads);
    cleanupDeadLocks(this.paths.locks);
    const state = this.stateStore.load();
    if (this.stateStore.isCompatibilityReadOnly()) return;
    recoverStagingDirectory(this.paths, state);
    recoverPreviousRuntimeDirectories(this.paths.runtimes);
  }
}

function throwIfCancelled(signal: AbortSignal | undefined, componentId: ManagedComponentId): void {
  if (!signal?.aborted) return;
  throw new ToolchainError({
    code: "TOOLCHAIN_CANCELLED",
    message: `Managed ${componentId} installation was cancelled`,
  });
}

const MAX_RECOVERY_ENTRIES = 512;

function safeDirectoryEntries(directory: string): Dirent[] {
  try {
    return fs.readdirSync(directory, { withFileTypes: true }).slice(0, MAX_RECOVERY_ENTRIES);
  } catch {
    return [];
  }
}

function cleanupPartialDownloads(directory: string): void {
  for (const entry of safeDirectoryEntries(directory)) {
    if (!entry.name.endsWith(".partial")) continue;
    try {
      fs.rmSync(path.join(directory, entry.name), { recursive: true, force: true });
    } catch {
      // A locked partial will be retried or replaced by the next install.
    }
  }
}

function cleanupDeadLocks(directory: string): void {
  for (const entry of safeDirectoryEntries(directory)) {
    if (!entry.isFile() || !entry.name.endsWith(".lock")) continue;
    const lockPath = path.join(directory, entry.name);
    try {
      const value = JSON.parse(fs.readFileSync(lockPath, "utf8")) as { pid?: unknown };
      if (typeof value.pid !== "number" || !isProcessAlive(value.pid)) fs.unlinkSync(lockPath);
    } catch {
      try {
        fs.unlinkSync(lockPath);
      } catch {
        // A concurrently locked entry remains protected by the filesystem.
      }
    }
  }
}

function recoverStagingDirectory(paths: ToolchainPaths, state: ToolchainPersistentState): void {
  const componentPattern = MANAGED_COMPONENT_IDS.join("|");
  const installPattern = new RegExp(`^(?:${componentPattern})-[A-Za-z0-9_-]+$`);
  const prunePattern = new RegExp(`^prune-(?:${componentPattern})-[A-Fa-f0-9-]+$`);
  const removePattern = new RegExp(`^remove-(${componentPattern})-[A-Fa-f0-9-]+$`);
  for (const entry of safeDirectoryEntries(paths.staging)) {
    const staged = path.join(paths.staging, entry.name);
    const remove = entry.name.match(removePattern);
    try {
      if (remove) {
        const componentId = remove[1] as ManagedComponentId;
        const original = path.join(paths.runtimes, componentId);
        if (state.managed[componentId] && !fs.existsSync(original)) fs.renameSync(staged, original);
        else fs.rmSync(staged, { recursive: true, force: true });
      } else if (installPattern.test(entry.name) || prunePattern.test(entry.name)) {
        fs.rmSync(staged, { recursive: true, force: true });
      }
    } catch {
      // Recovery is best-effort; discovery will report any remaining damage.
    }
  }
}

function recoverPreviousRuntimeDirectories(runtimes: string): void {
  for (const component of safeDirectoryEntries(runtimes)) {
    if (!component.isDirectory() || !(MANAGED_COMPONENT_IDS as readonly string[]).includes(component.name)) continue;
    const componentRoot = path.join(runtimes, component.name);
    for (const version of safeDirectoryEntries(componentRoot)) {
      if (!version.isDirectory() || version.isSymbolicLink()) continue;
      const versionRoot = path.join(componentRoot, version.name);
      for (const entry of safeDirectoryEntries(versionRoot)) {
        const match = entry.name.match(/^([a-z0-9_-]+-[a-z0-9_-]+)\.previous-[0-9a-f-]{36}$/i);
        if (!match || !entry.isDirectory() || entry.isSymbolicLink()) continue;
        const previous = path.join(versionRoot, entry.name);
        const active = path.join(versionRoot, match[1]!);
        try {
          if (fs.existsSync(active)) fs.rmSync(previous, { recursive: true, force: true });
          else fs.renameSync(previous, active);
        } catch {
          // Leave the previous runtime intact for a later recovery attempt.
        }
      }
    }
  }
}

type TrustedWindow = {
  isDestroyed(): boolean;
  webContents: {
    mainFrame: unknown;
  };
};

type IpcSender = {
  sender: unknown;
  senderFrame: unknown;
};

export function isTrustedDesktopIpcSender(window: TrustedWindow | null, event: IpcSender): boolean {
  return Boolean(
    window &&
    !window.isDestroyed() &&
    event.sender === window.webContents &&
    event.senderFrame === window.webContents.mainFrame,
  );
}

